class Solution:
    def shortestDistanceAfterQueries(self, n: int, queries: List[List[int]]) -> List[int]:
        graph = [[] for _ in range(n)]
        for i in range(n - 1):
            graph[i].append(i + 1)

        ans = []

        for u, v in queries:
            graph[u].append(v)

            dist = [-1] * n
            dist[0] = 0
            q = deque([0])

            while q:
                node = q.popleft()
                if node == n - 1:
                    break
                for nei in graph[node]:
                    if dist[nei] == -1:
                        dist[nei] = dist[node] + 1
                        q.append(nei)

            ans.append(dist[n - 1])

        return ans

class Solution:
    def shortestDistanceAfterQueries(self, n: int, queries: list[list[int]]) -> list[int]:
        dist = list(range(n))
        graph = [[] for _ in range(n)]
        ans = []

        for u, v in queries:
            graph[u].append(v)

            if dist[u] + 1 < dist[v]:
                dist[v] = dist[u] + 1
                queue = [v]
                head = 0

                while head < len(queue):
                    x = queue[head]
                    head += 1

                    if x + 1 < n and dist[x] + 1 < dist[x + 1]:
                        dist[x + 1] = dist[x] + 1
                        queue.append(x + 1)

                    for y in graph[x]:
                        if dist[x] + 1 < dist[y]:
                            dist[y] = dist[x] + 1
                            queue.append(y)

            ans.append(dist[n - 1])

        return ans

