        for i in range(n - 1):
            adj[i].append(i + 1)

        answer = []

        for u, v in queries:
            adj[u].append(v)

            # BFS from 0 to n-1
            dist = [-1] * n
            dist[0] = 0
            q = deque([0])
            while q:
                node = q.popleft()
                if node == n - 1:
                    break
                for nei in adj[node]:
