                        dist[nei] = dist[node] + 1
                        q.append(nei)

            answer.append(dist[n - 1])

        return answer

class Solution:
    def shortestDistanceAfterQueries(self, n, queries):
        dist = list(range(n))
        ans = []

        for u, v in queries:
            if dist[u] + 1 < dist[v]:
                dist[v] = dist[u] + 1
                for i in range(v + 1, n):
                    new_dist = min(dist[i], dist[i - 1] + 1)
                    if new_dist == dist[i]:
                        break
                    dist[i] = new_dist
            ans.append(dist[n - 1])

        return ans

This works because:

- Initially, the shortest distance to city i is just i, using the chain 0 -> 1 -> 2 -> ... -> i.
- When adding a road u -> v, the only immediate new possibility is reaching v in dist[u] + 1 steps.
- If that improves dist[v], then this improvement may propagate forward through the original chain edges v -> v+1 -> v+2 -> ...
- Since all roads go from smaller index to larger index, distances only need to be propagated forward.

Time complexity is O(n * q) in the worst case, which is fine for n, q <= 500.

class Solution:
    def shortestDistanceAfterQueries(self, n: int, queries: list[list[int]]) -> list[int]:
        # Build adjacency list with initial roads
        adj = [[] for _ in range(n)]
        for i in range(n - 1):
            adj[i].append(i + 1)

        # BFS to find shortest path from 0 to n-1
        def bfs():
            from collections import deque
            dist = [-1] * n
            dist[0] = 0
            q = deque([0])
            while q:
                node = q.popleft()
                for nei in adj[node]:
                    if dist[nei] == -1:
                        dist[nei] = dist[node] + 1
                        q.append(nei)
            return dist[n - 1]

        answer = []
        for u, v in queries:
            adj[u].append(v)
            answer.append(bfs())

        return answer

from bisect import bisect_left, bisect_right
from collections import defaultdict

class Fenwick:
    def __init__(self, n):
        self.n = n
        self.bit = [0] * (n + 2)

    def add(self, i, delta):
        while i <= self.n:
            self.bit[i] += delta
            i += i & -i

    def sum(self, i):
        s = 0
        while i > 0:
            s += self.bit[i]
            i -= i & -i
        return s

    def range_sum(self, l, r):
        if l > r:
            return 0
        return self.sum(r) - self.sum(l - 1)


class Segments:
    def __init__(self, n):
        self.n = n
        self.starts = []
        self.seg = {}
        self.bit_cnt = Fenwick(n)
        self.bit_sum = Fenwick(n)

    def _add_start(self, l):
        i = bisect_left(self.starts, l)
        self.starts.insert(i, l)

    def _remove_start(self, l):
        i = bisect_left(self.starts, l)
        self.starts.pop(i)

    def add_seg(self, l, r):
        self.seg[l] = r
        self._add_start(l)
        length = r - l + 1
        self.bit_cnt.add(length, 1)
        self.bit_sum.add(length, length)

    def remove_seg(self, l):
        r = self.seg.pop(l)
        self._remove_start(l)
        length = r - l + 1
        self.bit_cnt.add(length, -1)
        self.bit_sum.add(length, -length)
        return r

    def find_by_start(self, l):
        return self.seg.get(l)

    def find_containing(self, x):
        i = bisect_right(self.starts, x) - 1
        if i < 0:
            return None
        l = self.starts[i]
        r = self.seg[l]
        if l <= x <= r:
            return (l, r)
        return None

    def count_groups(self, k):
        total_cnt = self.bit_cnt.range_sum(k, self.n)
        total_sum = self.bit_sum.range_sum(k, self.n)
        return total_sum - (k - 1) * total_cnt


