                                segs.remove_seg(l1)
                                segs.remove_seg(l2)
                                segs.add_seg(l1, r2)
            bad[e] = 0

        def add_bad_edge(e):
            nonlocal total_bad
            if bad[e] == 1:
                return
            total_bad += 1
            x = (e + 1) % n
            info = segs.find_containing(x)
            if info is not None:
