                        info1 = segs.find_containing(prev_end)
                        if info1 is not None:
                            l1, r1 = info1
                            if r1 == prev_end:
                                segs.remove_seg(l1)
                                segs.remove_seg(l2)
                                segs.add_seg(l1, r2)
            bad[e] = 1

        def rebuild_if_all_good():
