from sortedcontainers import SortedList

class Solution:
    def numberOfAlternatingGroups(self, colors, queries):
        n = len(colors)
        breaks = SortedList()

        def is_break(i):
            return colors[i] == colors[(i + 1) % n]

        # Initialize breaks
        for i in range(n):
            if is_break(i):
                breaks.add(i)

        def count_alternating(k):
            num_breaks = len(breaks)
            if num_breaks == 0:
                return n
            # need k-1 consecutive non-break positions
            need = k - 1
            total = 0
            # gaps between consecutive breaks (circularly)
            for idx in range(num_breaks):
                b_cur = breaks[idx]
                if idx + 1 < num_breaks:
                    b_next = breaks[idx + 1]
                else:
                    b_next = breaks[0] + n  # wrap around
                gap = b_next - b_cur - 1
                if gap >= need:
                    total += gap - need + 1
            return total

        def update_break(i):
            # Recalculate whether position i is a break
            if is_break(i):
                if i not in breaks:
                    breaks.add(i)
            else:
                if i in breaks:
                    breaks.remove(i)

        result = []
        for q in queries:
            if q[0] == 1:
                size = q[1]
                result.append(count_alternating(size))
            else:
                idx, color = q[1], q[2]
                if colors[idx] != color:
                    colors[idx] = color
                    # Update breaks at idx and (idx-1) % n
                    update_break(idx)
                    update_break((idx - 1) % n)

        return result

