from sortedcontainers import SortedList

class Solution:
    def numberOfAlternatingGroups(self, colors, queries):
        n = len(colors)
        breaks = SortedList()

        # Initialize breaks
        for i in range(n):
            if colors[i] == colors[(i + 1) % n]:
                breaks.add(i)

        def count_groups(k):
            num_breaks = len(breaks)
            if num_breaks == 0:
                return n
            if k - 1 > n:
                return 0

            total = 0
            # Gaps between consecutive breaks (circularly)
            for idx in range(num_breaks):
                b_cur = breaks[idx]
                if idx + 1 < num_breaks:
                    b_next = breaks[idx + 1]
                else:
                    b_next = breaks[0] + n  # wrap around

                gap = b_next - b_cur - 1
                if gap >= k - 1:
                    total += gap - (k - 1) + 1

            return total

        def update_break(pos):
            # Check if position pos is a break and update accordingly
            is_break = colors[pos] == colors[(pos + 1) % n]
            in_set = pos in breaks
