    def numberOfAlternatingGroups(self, colors, queries):
        n = len(colors)

        same = [0] * n
        for i in range(n):
            same[i] = 1 if colors[i] == colors[(i + 1) % n] else 0

        if sum(same) == 0:
            return [n] * sum(1 for q in queries if q[0] == 1)

        left = list(range(n))
        right = list(range(n))
        alive = [False] * n

        for i in range(n):
            if same[i]:
                alive[i] = True

        for i in range(n):
            l = (i - 1 + n) % n
            r = (i + 1) % n
            while not alive[l] and l != i:
                l = (l - 1 + n) % n
            while not alive[r] and r != i:
                r = (r + 1) % n
            left[i] = l
            right[i] = r

        eq_positions = [i for i in range(n) if alive[i]]
        m = len(eq_positions)

        seg_len = {}
        bit_cnt = Fenwick(n)
        bit_sum = Fenwick(n)

        def add_segment(length, delta):
            if length <= 0:
                return
            seg_len[length] = seg_len.get(length, 0) + delta
            bit_cnt.add(length, delta)
            bit_sum.add(length, delta * length)

        if m == 1:
            add_segment(n, 1)
        else:
            for idx in range(m):
                a = eq_positions[idx]
                b = eq_positions[(idx + 1) % m]
                length = (b - a + n) % n
                if length == 0:
                    length = n
                add_segment(length, 1)

        def remove_pos(x):
            nonlocal m
            if not alive[x]:
                return
            if m == 1:
                add_segment(n, -1)
                alive[x] = False
                m = 0
                return

            l = left[x]
            r = right[x]

            len1 = (x - l + n) % n
            if len1 == 0:
                len1 = n
            len2 = (r - x + n) % n
            if len2 == 0:
                len2 = n
            len3 = (r - l + n) % n
            if len3 == 0:
                len3 = n

            add_segment(len1, -1)
            add_segment(len2, -1)
            add_segment(len3, 1)

            right[l] = r
            left[r] = l
            alive[x] = False
            m -= 1

        def add_pos(x):
            nonlocal m
            if alive[x]:
                return
            if m == 0:
                alive[x] = True
                left[x] = x
                right[x] = x
                add_segment(n, 1)
                m = 1
                return

            cur = (x - 1 + n) % n
            while not alive[cur]:
                cur = (cur - 1 + n) % n
            l = cur
            r = right[l]

            old_len = (r - l + n) % n
            if old_len == 0:
                old_len = n
            len1 = (x - l + n) % n
            if len1 == 0:
                len1 = n
            len2 = (r - x + n) % n
            if len2 == 0:
                len2 = n

            add_segment(old_len, -1)
            add_segment(len1, 1)
            add_segment(len2, 1)

            alive[x] = True
            left[x] = l
            right[x] = r
            right[l] = x
            left[r] = x
            m += 1

        def update_same(pos, new_val):
            if same[pos] == new_val:
                return
            if new_val == 1:
                same[pos] = 1
                add_pos(pos)
            else:
                same[pos] = 0
                remove_pos(pos)

        def query_k(k):
            if m == 0:
                return n
            total_cnt = bit_cnt.range_sum(k, n)
            total_sum = bit_sum.range_sum(k, n)
            return total_sum - (k - 1) * total_cnt

        ans = []
        for q in queries:
            if q[0] == 1:
                ans.append(query_k(q[1]))
            else:
                idx, c = q[1], q[2]
                if colors[idx] == c:
                    continue

                prev = (idx - 1 + n) % n
                update_same(prev, 1 if colors[prev] == c else 0)
                update_same(idx, 1 if c == colors[(idx + 1) % n] else 0)
                colors[idx] = c

        return ans

class Fenwick:
    def __init__(self, n):
        self.n = n
        self.bit = [0] * (n + 2)

    def add(self, i, delta):
        while i <= self.n:
            self.bit[i] += delta
            i += i & -i

    def sum(self, i):
        s = 0
        while i > 0:
            s += self.bit[i]
            i -= i & -i
        return s

    def range_sum(self, l, r):
        if l > r:
            return 0
        return self.sum(r) - self.sum(l - 1)


class Solution:
    def numberOfAlternatingGroups(self, colors, queries):
        n = len(colors)

        diff = [0] * n
        for i in range(n):
            diff[i] = 1 if colors[i] != colors[(i + 1) % n] else 0

        if all(x == 1 for x in diff):
            all_alt = True
        else:
            all_alt = False

        ans = []

        if all_alt:
            for q in queries:
                if q[0] == 1:
                    ans.append(n)
                else:
                    _, idx, c = q
                    if colors[idx] == c:
                        continue
                    colors[idx] = c
                    all_alt = False
                    break_start = idx
                    while diff[break_start] == 1:
                        break
                    diff[idx] = 1 if colors[idx] != colors[(idx + 1) % n] else 0
                    diff[(idx - 1) % n] = 1 if colors[(idx - 1) % n] != colors[idx] else 0
                    break
            else:
                return ans
        else:
            qstart = 0

        if all_alt:
            qstart = 0
            while qstart < len(queries):
                q = queries[qstart]
                if q[0] == 2:
                    _, idx, c = q
                    if colors[idx] != c:
                        break
                qstart += 1
            if qstart == len(queries):
                return ans
            for i in range(qstart):
                q = queries[i]
                if q[0] == 1:
                    pass
                else:
                    _, idx, c = q
                    colors[idx] = c
            diff = [0] * n
            for i in range(n):
                diff[i] = 1 if colors[i] != colors[(i + 1) % n] else 0
            all_alt = False

        zero_pos = set(i for i, v in enumerate(diff) if v == 0)

        def build_segments():
            if not zero_pos:
                return None, None, None, True
            z = min(zero_pos)
            lens = []
            starts = []
            seg_id_of_zero = {}
            cur = (z + 1) % n
            sid = 0
            for zp in sorted(zero_pos):
                pass
            zeros_sorted = sorted(zero_pos)
            m = len(zeros_sorted)
            for i in range(m):
                a = zeros_sorted[i]
                b = zeros_sorted[(i + 1) % m]
                length = (b - a - 1) % n
                lens.append(length)
                starts.append((a + 1) % n)
                seg_id_of_zero[a] = i
            pos_to_seg = {}
            for sid, st in enumerate(starts):
                L = lens[sid]
                for k in range(L):
                    pos_to_seg[(st + k) % n] = sid
            return lens, starts, pos_to_seg, False

        lens, starts, pos_to_seg, is_all_alt = build_segments()

        bit_cnt = Fenwick(n)
        bit_sum = Fenwick(n)
        seg_len_count = [0] * (n + 1)

        def add_len(L, delta):
            if L <= 0:
                return
            seg_len_count[L] += delta
            bit_cnt.add(L, delta)
            bit_sum.add(L, delta * L)

        if not is_all_alt:
            for L in lens:
                add_len(L, 1)

        def query_k(k):
            if is_all_alt_state[0]:
                return n
            total_cnt = bit_cnt.range_sum(k - 1, n)
            total_sum = bit_sum.range_sum(k - 1, n)
            return total_sum - (k - 2) * total_cnt

        is_all_alt_state = [is_all_alt]

        def rebuild():
            nonlocal lens, starts, pos_to_seg
            for L in range(1, n + 1):
                c = seg_len_count[L]
                if c:
                    bit_cnt.add(L, -c)
                    bit_sum.add(L, -c * L)
                    seg_len_count[L] = 0
            lens2, starts2, pos2, all2 = build_segments()
            lens, starts, pos_to_seg = lens2, starts2, pos2
            is_all_alt_state[0] = all2
            if not all2:
                for L in lens:
                    add_len(L, 1)

        for q in queries:
            if q[0] == 1:
                ans.append(query_k(q[1]))
            else:
                _, idx, c = q
                if colors[idx] == c:
                    continue
                colors[idx] = c
                diff[idx] = 1 if colors[idx] != colors[(idx + 1) % n] else 0
                diff[(idx - 1) % n] = 1 if colors[(idx - 1) % n] != colors[idx] else 0
                zero_pos = set(i for i, v in enumerate(diff) if v == 0)
                rebuild()

        return ans

