class Solution:
    def countOfPairs(self, nums):
        MOD = 10**9 + 7
        m = max(nums)

        dp = [0] * (m + 1)
        for a in range(nums[0] + 1):
            dp[a] = 1

        for i in range(1, len(nums)):
            ndp = [0] * (m + 1)
            prefix = [0] * (m + 1)
            prefix[0] = dp[0]
            for v in range(1, m + 1):
                prefix[v] = (prefix[v - 1] + dp[v]) % MOD

            diff = nums[i] - nums[i - 1]
            for a in range(nums[i] + 1):
                limit = a - max(diff, 0)
                if limit >= 0:
                    ndp[a] = prefix[limit]
            dp = ndp

        return sum(dp) % MOD

