            if counts[player][color] > player:
                winners.add(player)

        return len(winners)

class Solution:
    def winningPlayerCount(self, n: int, pick: list[list[int]]) -> int:
        from collections import defaultdict
        # For each player, count how many balls of each color they picked
        player_colors = defaultdict(lambda: defaultdict(int))
        for x, y in pick:
            player_colors[x][y] += 1

        count = 0
        for player in range(n):
            # Player i wins if they have strictly more than i balls of the same color
            if player in player_colors:
                if max(player_colors[player].values()) > player:
                    count += 1
        return count

