    def minFlips(self, grid):
        m, n = len(grid), len(grid[0])

        row_flips = 0
        for i in range(m):
            l, r = 0, n - 1
            while l < r:
                if grid[i][l] != grid[i][r]:
                    row_flips += 1
                l += 1
                r -= 1

