class Solution:
    def timeTaken(self, edges):
        n = len(edges) + 1
        g = [[] for _ in range(n)]
        for u, v in edges:
            g[u].append(v)
            g[v].append(u)

        def cost(v):
            return 1 if v & 1 else 2

        down = [0] * n

        def dfs1(u, p):
            best = 0
            for v in g[u]:
                if v == p:
                    continue
                dfs1(v, u)
                cand = cost(v) + down[v]
                if cand > best:
                    best = cand
            down[u] = best

        dfs1(0, -1)

        ans = [0] * n

        def dfs2(u, p, up):
            ans[u] = max(down[u], up)

            mx1 = -1
            mx2 = -1
            who = -1
            for v in g[u]:
                if v == p:
                    continue
                val = cost(v) + down[v]
                if val > mx1:
                    mx2 = mx1
                    mx1 = val
                    who = v
                elif val > mx2:
                    mx2 = val

            for v in g[u]:
                if v == p:
                    continue
                best_excluding_v = mx2 if who == v else mx1
                use_from_u = up
                if best_excluding_v > use_from_u:
                    use_from_u = best_excluding_v
                child_up = cost(u) + use_from_u
                dfs2(v, u, child_up)

        dfs2(0, -1, 0)
        return ans

