import sys

class Solution:
    def timeTaken(self, edges: List[List[int]]) -> List[int]:
        sys.setrecursionlimit(1 << 20)

        n = len(edges) + 1
        g = [[] for _ in range(n)]
        for u, v in edges:
            g[u].append(v)
            g[v].append(u)

        def w(v: int) -> int:
            return 1 if v & 1 else 2

        down = [0] * n

        def dfs1(u: int, p: int) -> None:
            best = 0
            for v in g[u]:
                if v == p:
                    continue
                dfs1(v, u)
                cand = w(v) + down[v]
                if cand > best:
                    best = cand
            down[u] = best

        dfs1(0, -1)

        ans = [0] * n

        def dfs2(u: int, p: int, up: int) -> None:
            vals = []
            for v in g[u]:
                if v == p:
                    vals.append(up)
                else:
                    vals.append(w(v) + down[v])

            m = len(vals)
            pref = [0] * m
            suff = [0] * m

            for i in range(m):
                pref[i] = vals[i] if i == 0 else max(pref[i - 1], vals[i])
            for i in range(m - 1, -1, -1):
                suff[i] = vals[i] if i == m - 1 else max(suff[i + 1], vals[i])

            ans[u] = pref[-1] if m else 0

            for i, v in enumerate(g[u]):
                if v == p:
                    continue
                best_excluding_v = 0
                if i > 0:
                    best_excluding_v = max(best_excluding_v, pref[i - 1])
                if i + 1 < m:
                    best_excluding_v = max(best_excluding_v, suff[i + 1])
                new_up = w(u) + best_excluding_v
                dfs2(v, u, new_up)

        dfs2(0, -1, 0)
        return ans

class Solution:
    def countKConstraintSubstrings(self, s: str, k: int) -> int:
        left = 0
        zeros = 0
        ones = 0
        ans = 0

        for right, ch in enumerate(s):
            if ch == '0':
                zeros += 1
            else:
                ones += 1

            while zeros > k and ones > k:
                if s[left] == '0':
                    zeros -= 1
                else:
                    ones -= 1
