        weights = [0] * m
        for i in range(m):
            j = n - 1 - i
            if i == j:
                weights[i] = pow10[i] % 7
            else:
                weights[i] = (pow10[i] + pow10[j]) % 7

        dp = [[False] * 7 for _ in range(m + 1)]
        dp[m][0] = True

        for i in range(m - 1, -1, -1):
            start = 1 if i == m - 1 and n == 1 else 0
            if i == 0:
                start = 1
            for rem in range(7):
                ok = False
                for d in range(start, 10):
                    nr = (rem + d * weights[i]) % 7
                    if dp[i + 1][nr]:
                        ok = True
                        break
                dp[i][rem] = ok

        ans_half = []
        rem = 0
        for i in range(m):
            low = 1 if i == 0 else 0
            for d in range(9, low - 1, -1):
                nr = (rem + d * weights[i]) % 7
                if dp[i + 1][nr]:
