    def _solve7(self, n: int) -> str:
        pow10 = [1] * n
        for i in range(1, n):
            pow10[i] = (pow10[i - 1] * 10) % 7

        pairs = []
        half = n // 2
        for i in range(half):
            w = (pow10[i] + pow10[n - 1 - i]) % 7
            pairs.append(w)

        center_weight = pow10[half] % 7 if n % 2 == 1 else 0

        suffix = [False] * 7
        suffix[0] = True

        for idx in range(len(pairs) - 1, -1, -1):
            w = pairs[idx]
            nxt = [False] * 7
            start = 1 if idx == 0 else 0
            for rem in range(7):
                if not suffix[rem]:
                    continue
                for d in range(start, 10):
                    nr = (d * w + rem) % 7
                    nxt[nr] = True
            suffix = nxt

        res = ['0'] * n
        rem = 0

        for idx in range(len(pairs)):
            w = pairs[idx]
            start = 1 if idx == 0 else 0

            future = [False] * 7
            future[0] = True
            for j in range(len(pairs) - 1, idx, -1):
                ww = pairs[j]
                nxt = [False] * 7
                st = 1 if j == 0 else 0
                for rr in range(7):
                    if not future[rr]:
                        continue
                    for d in range(st, 10):
                        nxt[(d * ww + rr) % 7] = True
                future = nxt

            chosen = -1
            for d in range(9, start - 1, -1):
                nr = (rem + d * w) % 7
                ok = False
                if idx == len(pairs) - 1:
                    if n % 2 == 0:
                        ok = (nr % 7 == 0)
                    else:
                        for c in range(9, -1, -1):
                            if (nr + c * center_weight) % 7 == 0:
                                ok = True
                                break
                else:
                    target = (-nr) % 7
                    if future[target]:
                        ok = True
                if ok:
                    chosen = d
                    rem = nr
                    res[idx] = res[n - 1 - idx] = str(d)
                    break

        if n % 2 == 1:
            cidx = n // 2
            for d in range(9, -1, -1):
                if (rem + d * center_weight) % 7 == 0:
                    res[cidx] = str(d)
                    break

        return ''.join(res)

