    def maxScore(self, grid):
        m = len(grid)

        value_to_rows = {}
        for r, row in enumerate(grid):
            for v in set(row):
                if v not in value_to_rows:
                    value_to_rows[v] = 0
                value_to_rows[v] |= 1 << r

        values = sorted(value_to_rows.keys())

        dp = {0: 0}

        for v in values:
            rows_mask = value_to_rows[v]
            new_dp = dp.copy()

            sub = rows_mask
            while sub:
                bit = sub & -sub
                sub -= bit
                for mask, score in dp.items():
                    if mask & bit == 0:
                        nm = mask | bit
                        ns = score + v
                        if ns > new_dp.get(nm, 0):
                            new_dp[nm] = ns

            dp = new_dp

        return max(dp.values())

