class Solution:
    def maxScore(self, grid):
        m = len(grid)

        # 每一行去重，因为同一行里相同值重复出现没有意义
        rows = [set(row) for row in grid]

        # 收集每个值可以来自哪些行
        val_to_rows = {}
        for r in range(m):
            for v in rows[r]:
                if v not in val_to_rows:
                    val_to_rows[v] = []
                val_to_rows[v].append(r)

        # 只需要考虑出现过的值，按值从大到小做决策
        values = sorted(val_to_rows.keys(), reverse=True)
        n = len(values)

        # dp(i, mask): 从 values[i:] 中选择，mask 表示哪些行已经被占用
        memo = {}

        def dfs(i, mask):
            if i == n:
                return 0
            key = (i, mask)
            if key in memo:
                return memo[key]

            # 不选当前值
            ans = dfs(i + 1, mask)

            # 选当前值，把它分配给某个还没使用的行
            v = values[i]
            for r in val_to_rows[v]:
                if (mask >> r) & 1 == 0:
                    ans = max(ans, v + dfs(i + 1, mask | (1 << r)))

            memo[key] = ans
            return ans

        return dfs(0, 0)

