class Solution:
    def maxPossibleScore(self, start, d):
        start.sort()

        def can(gap):
            prev = start[0]
            for i in range(1, len(start)):
                cur = max(start[i], prev + gap)
                if cur > start[i] + d:
                    return False
                prev = cur
            return True

        left, right = 0, start[-1] + d - start[0]
        while left < right:
            mid = (left + right + 1) // 2
            if can(mid):
                left = mid
            else:
                right = mid - 1
        return left

This works by:

- Sorting intervals by start.
- Binary searching the answer `gap`.
- Greedily checking if we can pick one number from each interval so that every next chosen number is at least `gap` larger than the previous one.
- Since the chosen numbers are in sorted interval order, ensuring adjacent differences are at least `gap` guarantees every pair differs by at least `gap`.

Time complexity: O(n log M), where `M = max(start) + d - min(start)`.
Space complexity: O(1) extra (ignoring sort internals).

class Solution:
    def maxPossibleScore(self, start: list[int], d: int) -> int:
        start.sort()
        n = len(start)

        def canAchieve(score):
            # Greedily pick the smallest possible value from each interval
            # such that it's at least `score` away from the previous pick
            prev = start[0]
            for i in range(1, n):
                # Next value must be >= prev + score and >= start[i]
                next_val = max(prev + score, start[i])
                # Check if next_val is within the interval [start[i], start[i] + d]
                if next_val > start[i] + d:
                    return False
                prev = next_val
            return True

        lo, hi = 0, (start[-1] + d - start[0]) // (n - 1) + 1

        while lo < hi:
            mid = (lo + hi + 1) // 2
            if canAchieve(mid):
                lo = mid
            else:
                hi = mid - 1

        return lo

