from functools import lru_cache
from typing import List

class Solution:
    def maxMoves(self, kx: int, ky: int, positions: List[List[int]]) -> int:
        points = [(kx, ky)] + [tuple(p) for p in positions]
        n = len(positions)
        m = n + 1

        moves = [(2, 1), (2, -1), (-2, 1), (-2, -1),
                 (1, 2), (1, -2), (-1, 2), (-1, -2)]

        def bfs(sx: int, sy: int):
            dist = [[-1] * 50 for _ in range(50)]
            q = deque([(sx, sy)])
            dist[sx][sy] = 0
            while q:
                x, y = q.popleft()
                for dx, dy in moves:
                    nx, ny = x + dx, y + dy
                    if 0 <= nx < 50 and 0 <= ny < 50 and dist[nx][ny] == -1:
                        dist[nx][ny] = dist[x][y] + 1
                        q.append((nx, ny))
            return dist

        d = [[0] * m for _ in range(m)]
        all_dists = [bfs(x, y) for x, y in points]
        for i in range(m):
            for j in range(m):
                x, y = points[j]
                d[i][j] = all_dists[i][x][y]

        @lru_cache(None)
        def dp(pos_idx: int, mask: int, turn: int) -> int:
            if mask == (1 << n) - 1:
                return 0

            if turn == 0:  # Alice maximizes
                best = 0
                for i in range(n):
                    if not (mask >> i) & 1:
                        best = max(best, d[pos_idx][i + 1] + dp(i + 1, mask | (1 << i), 1))
                return best
            else:  # Bob minimizes
                best = float('inf')
                for i in range(n):
                    if not (mask >> i) & 1:
                        best = min(best, d[pos_idx][i + 1] + dp(i + 1, mask | (1 << i), 0))
                return best

        return dp(0, 0, 0)

