class Solution:
    def maxScore(self, a: list[int], b: list[int]) -> int:
        # dp[j] = best score achievable having matched a[0..j] using some indices from b
        # We process elements of b left to right, maintaining dp for 4 stages.

        NEG_INF = float('-inf')
        dp = [NEG_INF] * 4

        for val in b:
            # Process in reverse to avoid using the same b element twice in one step
            for j in range(3, -1, -1):
                prev = dp[j - 1] if j > 0 else 0
                if prev != NEG_INF:
                    candidate = prev + a[j] * val
                    if candidate > dp[j]:
                        dp[j] = candidate

        return dp[3]

