    def maxValue(self, nums, k):
        n = len(nums)
        MAXV = 128

        left = [[False] * MAXV for _ in range(k + 1)]
        left[0][0] = True
        pref = [None] * n

        for i, x in enumerate(nums):
            for cnt in range(min(k - 1, i), -1, -1):
                row = left[cnt]
                nxt = left[cnt + 1]
                for v in range(MAXV):
                    if row[v]:
                        nxt[v | x] = True
            pref[i] = [s[:] for s in left]

        right = [[False] * MAXV for _ in range(k + 1)]
        right[0][0] = True
        suff = [None] * n

        for i in range(n - 1, -1, -1):
            x = nums[i]
            taken = n - 1 - i
            for cnt in range(min(k - 1, taken), -1, -1):
                row = right[cnt]
                nxt = right[cnt + 1]
                for v in range(MAXV):
                    if row[v]:
                        nxt[v | x] = True
            suff[i] = [s[:] for s in right]

        ans = 0

        for split in range(n - 1):
            if split + 1 < k or n - (split + 1) < k:
                continue

            left_vals = pref[split][k]
            right_vals = suff[split + 1][k]

            for a in range(MAXV):
                if not left_vals[a]:
                    continue
                for b in range(MAXV):
                    if right_vals[b]:
                        ans = max(ans, a ^ b)

        return ans

