            if val > self.bit[i]:
                self.bit[i] = val
            i += i & -i

    def query(self, i):
        res = 0
        while i > 0:
            if self.bit[i] > res:
                res = self.bit[i]
            i -= i & -i
        return res


class Solution:
    def maxPathLength(self, coordinates, k):
        xk, yk = coordinates[k]

        left = []
        right = []

        for x, y in coordinates:
            if x < xk and y < yk:
                left.append((x, y))
            elif x > xk and y > yk:
                right.append((x, y))

        def lis_2d(points):
            if not points:
                return 0

            ys = sorted({y for _, y in points})
            comp = {y: i + 1 for i, y in enumerate(ys)}

            points.sort(key=lambda p: (p[0], -p[1]))

            bit = BIT(len(ys))
            ans = 0
            i = 0
            n = len(points)

            while i < n:
                j = i
                pending = []
                x = points[i][0]
                while j < n and points[j][0] == x:
                    y = points[j][1]
                    idx = comp[y]
                    best = bit.query(idx - 1) + 1
                    pending.append((idx, best))
                    if best > ans:
                        ans = best
                    j += 1
                for idx, best in pending:
                    bit.update(idx, best)
                i = j

            return ans

        return lis_2d(left) + 1 + lis_2d(right)

