        def lis_length(points):
            if not points:
                return 0

            points.sort(key=lambda p: (p[0], -p[1]))
            tails = []

            for _, y in points:
                l, r = 0, len(tails)
                while l < r:
                    m = (l + r) // 2
                    if tails[m] < y:
                        l = m + 1
                    else:
                        r = m
                if l == len(tails):
                    tails.append(y)
                else:
                    tails[l] = y
