    def minNumberOfSeconds(self, mountainHeight, workerTimes):
        def can_finish(t):
            total = 0
            for w in workerTimes:
                # Maximum x such that w * x * (x + 1) // 2 <= t
                lo, hi = 0, mountainHeight
                while lo < hi:
                    mid = (lo + hi + 1) // 2
                    if w * mid * (mid + 1) // 2 <= t:
                        lo = mid
                    else:
