    def minNumberOfSeconds(self, mountainHeight: int, workerTimes: list[int]) -> int:
        import math

        def canFinish(T):
            # For a given time T, each worker i can reduce height by x_i
            # where workerTimes[i] * x_i * (x_i + 1) / 2 <= T
            # x_i * (x_i + 1) <= 2 * T / workerTimes[i]
            # x_i <= (-1 + sqrt(1 + 8*T/workerTimes[i])) / 2
            total = 0
            for w in workerTimes:
                # solve x*(x+1)/2 <= T/w
                ratio = 2 * T / w
                x = int((-1 + math.isqrt(1 + 4 * ratio)) // 2)
                total += x
                if total >= mountainHeight:
                    return True
            return total >= mountainHeight

        lo, hi = 1, min(workerTimes) * mountainHeight * (mountainHeight + 1) // 2
        while lo < hi:
            mid = (lo + hi) // 2
            if canFinish(mid):
                hi = mid
            else:
                lo = mid + 1
        return lo

