            (a, b, c),
            (a, c, b),
            (b, a, c),
            (b, c, a),
            (c, a, b),
            (c, b, a),
        ]

        ans = 0
        for x, y, z in orders:
            val = (((x << bits(y)) | y) << bits(z)) | z
            ans = max(ans, val)

        return ans

