class Solution:
    def gcdValues(self, nums: List[int], queries: List[int]) -> List[int]:
        maxv = max(nums)

        freq = [0] * (maxv + 1)
        for x in nums:
            freq[x] += 1

        # cnt_mult[d] = how many numbers in nums are divisible by d
        cnt_mult = [0] * (maxv + 1)
        for d in range(1, maxv + 1):
            s = 0
            for m in range(d, maxv + 1, d):
                s += freq[m]
            cnt_mult[d] = s

        # exact[d] = number of pairs with gcd exactly d
        exact = [0] * (maxv + 1)
        for d in range(maxv, 0, -1):
            c = cnt_mult[d]
            total = c * (c - 1) // 2
            sub = 0
            for m in range(d + d, maxv + 1, d):
                sub += exact[m]
            exact[d] = total - sub

        # prefix over gcd values in sorted gcdPairs
        prefix = [0] * (maxv + 1)
        for d in range(1, maxv + 1):
            prefix[d] = prefix[d - 1] + exact[d]

        ans = []
        for q in queries:
            lo, hi = 1, maxv
            while lo < hi:
                mid = (lo + hi) // 2
                if prefix[mid] > q:
                    hi = mid
                else:
                    lo = mid + 1
            ans.append(lo)

        return ans

