    def minStartingIndex(self, s: str, pattern: str) -> int:
        n = len(s)
        m = len(pattern)
        if m > n:
            return -1

        base = 911382323
        mod1 = 1000000007
        mod2 = 1000000009

        def build_hash(t, mod):
            h = [0] * (len(t) + 1)
            p = [1] * (len(t) + 1)
            for i, ch in enumerate(t):
                h[i + 1] = (h[i] * base + (ord(ch) - 96)) % mod
                p[i + 1] = (p[i] * base) % mod
            return h, p

        hs1, ps1 = build_hash(s, mod1)
        hs2, ps2 = build_hash(s, mod2)
        hp1, pp1 = build_hash(pattern, mod1)
        hp2, pp2 = build_hash(pattern, mod2)

        def get_hash(h, p, l, r, mod):
            return (h[r] - h[l] * p[r - l]) % mod

        def equal_sub(i, l, r):
            a1 = get_hash(hs1, ps1, i + l, i + r, mod1)
            b1 = get_hash(hp1, pp1, l, r, mod1)
            if a1 != b1:
                return False
            a2 = get_hash(hs2, ps2, i + l, i + r, mod2)
            b2 = get_hash(hp2, pp2, l, r, mod2)
            return a2 == b2

        for i in range(n - m + 1):
            if equal_sub(i, 0, m):
                return i

            lo, hi = 0, m
            while lo < hi:
                mid = (lo + hi) // 2
                if equal_sub(i, 0, mid + 1):
                    lo = mid + 1
                else:
                    hi = mid
            first_mismatch = lo

            if first_mismatch < m and equal_sub(i, first_mismatch + 1, m):
                return i

        return -1

