        z1 = z_function(pattern + sep + s)
        pref = [0] * (n - m + 1)
        base = m + 1
        for i in range(n - m + 1):
            pref[i] = min(z1[base + i], m)

        # suffix matches: longest common suffix of pattern and s[i:i+m]
        rs = s[::-1]
        rp = pattern[::-1]
        z2 = z_function(rp + sep + rs)
        suff = [0] * (n - m + 1)
        base2 = m + 1
        for i in range(n - m + 1):
            rev_start = n - (i + m)
            suff[i] = min(z2[base2 + rev_start], m)

        for i in range(n - m + 1):
            if pref[i] == m:
                return i
            if pref[i] + suff[i] >= m - 1:
                return i

        return -1

