    def minStartingIndex(self, s: str, pattern: str) -> int:
        n = len(s)
        m = len(pattern)
        if m > n:
            return -1

        base = 911382323
        mod1 = 1000000007
        mod2 = 1000000009

        pow1 = [1] * (max(n, m) + 1)
        pow2 = [1] * (max(n, m) + 1)
        for i in range(1, len(pow1)):
            pow1[i] = (pow1[i - 1] * base) % mod1
            pow2[i] = (pow2[i - 1] * base) % mod2

        def build_hash(arr, mod):
            h = [0] * (len(arr) + 1)
            for i, ch in enumerate(arr):
                h[i + 1] = (h[i] * base + (ord(ch) - 96)) % mod
            return h

        hs1 = build_hash(s, mod1)
        hs2 = build_hash(s, mod2)
        hp1 = build_hash(pattern, mod1)
        hp2 = build_hash(pattern, mod2)

        def get_hash(h, l, r, pw, mod):
            return (h[r] - h[l] * pw[r - l]) % mod

        def equal_sub(i, j, length):
            return (
                get_hash(hs1, i, i + length, pow1, mod1) == get_hash(hp1, j, j + length, pow1, mod1)
                and
                get_hash(hs2, i, i + length, pow2, mod2) == get_hash(hp2, j, j + length, pow2, mod2)
            )

        for start in range(n - m + 1):
            if equal_sub(start, 0, m):
                return start

            lo, hi = 0, m
            while lo < hi:
                mid = (lo + hi) // 2
                if equal_sub(start, 0, mid + 1):
                    lo = mid + 1
                else:
                    hi = mid
            first_mismatch = lo

            if first_mismatch < m and equal_sub(start + first_mismatch + 1, first_mismatch + 1, m - first_mismatch - 1):
                return start

        return -1

class Solution:
    def findXSum(self, nums, k, x):
        n = len(nums)
        ans = []

        for i in range(n - k + 1):
            freq = {}
            for v in nums[i:i + k]:
                freq[v] = freq.get(v, 0) + 1

            items = sorted(freq.items(), key=lambda p: (-p[1], -p[0]))
            total = 0
            for value, count in items[:x]:
                total += value * count
            ans.append(total)

        return ans

