    def countWinningSequences(self, s: str) -> int:
        MOD = 10**9 + 7
        n = len(s)

        idx = {'F': 0, 'W': 1, 'E': 2}
        a = [idx[c] for c in s]

        def score(b, x):
            if b == x:
                return 0
            if (b == 0 and x == 2) or (b == 1 and x == 0) or (b == 2 and x == 1):
                return 1
            return -1

        offset = n
        size = 2 * n + 1

        dp = [[0] * size for _ in range(3)]

        for b in range(3):
            d = score(b, a[0])
            dp[b][offset + d] = 1

        for i in range(1, n):
            ndp = [[0] * size for _ in range(3)]
            for prev in range(3):
                row = dp[prev]
                for diff_idx in range(size):
                    cnt = row[diff_idx]
                    if cnt == 0:
                        continue
                    for cur in range(3):
                        if cur == prev:
                            continue
                        nd = diff_idx + score(cur, a[i])
                        ndp[cur][nd] = (ndp[cur][nd] + cnt) % MOD
            dp = ndp

        ans = 0
        for last in range(3):
            for diff_idx in range(offset + 1, size):
                ans = (ans + dp[last][diff_idx]) % MOD

        return ans

Looking at this problem, I need to count Bob's sequences where:
1. Bob never uses the same creature in two consecutive rounds
2. Bob's total points strictly exceed Alice's total points

**Key observations:**
- Each round, based on Alice's and Bob's choices, the score difference changes by -1, 0, or +1 (from Bob's perspective)
- The score difference ranges from -n to +n, but we only care about Bob ending with score > 0 (i.e., difference > 0 from Bob's perspective)
- Bob has 3 choices per round but can't repeat consecutive choices

**DP State:** `dp[i][last_bob_move][score_difference]` = number of ways

Since n can be up to 1000, score difference ranges from -1000 to 1000. I'll offset by n to make indices non-negative.

Let me map creatures: F=0, W=1, E=2

**Scoring:** For Bob's choice `b` vs Alice's choice `a`:
- If same: 0 (no points)
- F beats E: if b=F, a=E → Bob +1 (diff +1)
- W beats F: if b=W, a=F → Bob +1 (diff +1)  
- E beats W: if b=E, a=W → Bob +1 (diff +1)
- Otherwise the reverse: Alice gets point (diff -1)

So `delta(b, a)`: if b==a → 0, if (b-a)%3 == 1 → -1 (Alice wins), if (b-a)%3 == 2 → +1 (Bob wins). Let me verify:
- b=F(0), a=E(2): (0-2)%3 = 1... that should be Bob +1. Let me reconsider.
- F beats E, W beats F, E beats W. So winner beats loser: F>E, W>F, E>W.
- b=0(F), a=2(E): Bob wins. (0-2)%3 = 1. So (b-a)%3==1 means Bob wins → +1.
- b=1(W), a=0(F): Bob wins. (1-0)%3 = 1. Confirmed.
- b=2(E), a=1(W): Bob wins. (2-1)%3 = 1. Confirmed.
- So (b-a)%3==1 → +1, (b-a)%3==2 → -1.

For DP, score difference can range from -n to n. I only need to track differences where Bob ends up > 0. I'll use offset = n so index 0 means difference = -n.

```python
class Solution:
    def countWinningSequences(self, s: str) -> int:
        MOD = 10**9 + 7
        n = len(s)
        mapping = {'F': 0, 'W': 1, 'E': 2}
        alice = [mapping[c] for c in s]

        # dp[last_move][score_diff + n] = number of ways
        # score_diff ranges from -n to n, so offset by n
        # last_move: 0, 1, 2

        size = 2 * n + 1
        # Initialize with None (no rounds processed yet)
        # After round 0:
        dp = [[0] * size for _ in range(3)]

        a = alice[0]
        for b in range(3):
            if b == a:
                delta = 0
            elif (b - a) % 3 == 1:
                delta = 1
            else:
                delta = -1
            idx = delta + n
            if 0 <= idx < size:
                dp[b][idx] = 1

        for i in range(1, n):
            a = alice[i]
            new_dp = [[0] * size for _ in range(3)]
            for b in range(3):
                if b == a:
                    delta = 0
                elif (b - a) % 3 == 1:
                    delta = 1
                else:
                    delta = -1
                for prev_b in range(3):
                    if prev_b == b:
                        continue
                    prev_row = dp[prev_b]
                    new_row = new_dp[b]
                    if delta == 1:
                        for d in range(size - 1):
                            if prev_row[d]:
                                new_row[d + 1] = (new_row[d + 1] + prev_row[d]) % MOD
                    elif delta == -1:
                        for d in range(1, size):
                            if prev_row[d]:
                                new_row[d - 1] = (new_row[d - 1] + prev_row[d]) % MOD
                    else:
                        for d in range(size):
                            if prev_row[d]:
                                new_row[d] = (new_row[d] + prev_row[d]) % MOD
            dp = new_dp

        ans = 0
        for b in range(3):
            for d in range(n + 1, size):  # score_diff > 0 means index > n
                ans = (ans + dp[b][d]) % MOD

        return ans
