class Solution:
    def countWinningSequences(self, s: str) -> int:
        MOD = 10**9 + 7
        n = len(s)

        moves = {'F': 0, 'W': 1, 'E': 2}

        def score(bob, alice):
            if bob == alice:
                return 0
            if (bob == 0 and alice == 2) or (bob == 1 and alice == 0) or (bob == 2 and alice == 1):
                return 1
            return -1

        offset = n
        size = 2 * n + 1

        dp = [[0] * size for _ in range(4)]

        first_alice = moves[s[0]]
        for bob in range(3):
            diff = score(bob, first_alice)
            dp[bob][diff + offset] = 1

        for i in range(1, n):
            ndp = [[0] * size for _ in range(4)]
            alice = moves[s[i]]
            remaining = n - i - 1

            for last in range(3):
                row = dp[last]
                for d in range(size):
                    cnt = row[d]
                    if cnt == 0:
                        continue

                    cur_diff = d - offset

                    for bob in range(3):
                        if bob == last:
                            continue
                        new_diff = cur_diff + score(bob, alice)

                        if new_diff + remaining < 1:
                            continue

                        ndp[bob][new_diff + offset] = (ndp[bob][new_diff + offset] + cnt) % MOD

            dp = ndp

        ans = 0
        for last in range(3):
            for d in range(offset + 1, size):
                ans = (ans + dp[last][d]) % MOD

        return ans

Looking at this problem, I need to count Bob's sequences where:
1. Bob never uses the same creature in two consecutive rounds
2. Bob's total points strictly exceed Alice's total points

**Key observations:**
- Each round, based on Alice's and Bob's choices, the score difference changes by -1, 0, or +1 (from Bob's perspective)
- I need to track: current round, Bob's last move, and the current score difference
- The score difference ranges from -n to +n, but I can optimize

**DP State:** `dp[i][last_move][score_diff]` = number of ways for Bob to play rounds 0..i with `last_move` as Bob's move in round i, achieving a score difference of `score_diff` (Bob's points - Alice's points).

Since n can be up to 1000, score_diff ranges from -1000 to 1000. I'll offset by n to index into an array.

For each round, Bob has 3 choices (F, W, E), but must differ from previous round's choice.

Let me map: F=0, W=1, E=2. The "beats" relationship:
- F beats E (Fire beats Earth Golem)
- W beats F (Water beats Fire Dragon)  
- E beats W (Earth beats Water Serpent)

So creature `b` beats creature `a` when: (b=0,a=2), (b=1,a=0), (b=2,a=1) → b beats a if `(b - a) % 3 == 1` → wait let me check: 0-2 = -2 ≡ 1 mod 3 ✓, 1-0=1 ✓, 2-1=1 ✓. Yes.

And `a` beats `b` if `(a - b) % 3 == 1`, i.e., `(b - a) % 3 == 2`.

Score change for Bob: +1 if `(b-a)%3==1`, -1 if `(b-a)%3==2`, 0 if `b==a`.

At the end, Bob wins if score_diff > 0.

```python
class Solution:
    def countWinningSequences(self, s: str) -> int:
        MOD = 10**9 + 7
        n = len(s)
        mapping = {'F': 0, 'W': 1, 'E': 2}
        alice = [mapping[c] for c in s]

        # dp[last_move][score_diff + n] = number of ways
        # score_diff ranges from -n to n, offset by n
        size = 2 * n + 1

        # Initialize: no previous move yet
        # Use last_move = 0,1,2 and a sentinel 3 for "no previous"
        # For round 0, any move is valid

        # dp[bob_move][score_offset]
        dp = [[0] * size for _ in range(3)]

        a = alice[0]
        for b in range(3):
            diff = (b - a) % 3
            if diff == 1:
                delta = 1
            elif diff == 2:
                delta = -1
            else:
                delta = 0
            idx = delta + n
            if 0 <= idx < size:
                dp[b][idx] = 1

        for i in range(1, n):
            a = alice[i]
            new_dp = [[0] * size for _ in range(3)]
            for b in range(3):
                diff = (b - a) % 3
                if diff == 1:
                    delta = 1
                elif diff == 2:
                    delta = -1
                else:
                    delta = 0
                for prev_b in range(3):
                    if prev_b == b:
                        continue
                    prev_row = dp[prev_b]
                    target_row = new_dp[b]
                    # new score = old score + delta
                    # new_idx = old_idx + delta
                    if delta == 1:
                        for j in range(size - 1):
                            if prev_row[j]:
                                target_row[j + 1] = (target_row[j + 1] + prev_row[j]) % MOD
                    elif delta == -1:
                        for j in range(1, size):
                            if prev_row[j]:
                                target_row[j - 1] = (target_row[j - 1] + prev_row[j]) % MOD
                    else:
                        for j in range(size):
                            if prev_row[j]:
                                target_row[j] = (target_row[j] + prev_row[j]) % MOD
            dp = new_dp

        # Sum all dp[b][score_offset] where score_offset > n (i.e., score_diff > 0)
        ans = 0
        for b in range(3):
            for j in range(n + 1, size):
                ans = (ans + dp[b][j]) % MOD

        return ans
