class Solution:
    def countWinningSequences(self, s: str) -> int:
        MOD = 10**9 + 7
        n = len(s)

        mp = {'F': 0, 'W': 1, 'E': 2}

        def score(b, a):
            if b == a:
                return 0
            if (b == 0 and a == 2) or (b == 1 and a == 0) or (b == 2 and a == 1):
                return 1
            return -1

        vals = [mp[c] for c in s]

        # dp[last][diff] = number of ways after current rounds
        # diff means BobScore - AliceScore, shifted by n
        size = 2 * n + 1
        offset = n

        dp = [[0] * size for _ in range(3)]

        a0 = vals[0]
        for b in range(3):
            d = score(b, a0)
            dp[b][offset + d] = 1

        for i in range(1, n):
            ndp = [[0] * size for _ in range(3)]
            a = vals[i]
            for last in range(3):
                row = dp[last]
                for idx in range(size):
                    cnt = row[idx]
                    if cnt == 0:
                        continue
                    for b in range(3):
                        if b == last:
                            continue
                        nd = idx + score(b, a)
                        ndp[b][nd] = (ndp[b][nd] + cnt) % MOD
            dp = ndp

        ans = 0
        for last in range(3):
            for idx in range(offset + 1, size):
                ans = (ans + dp[last][idx]) % MOD

        return ans

