class Solution:
    def numberOfSubstrings(self, s: str, k: int) -> int:
        n = len(s)
        if k == 1:
            return n * (n + 1) // 2

        cnt = [0] * 26
        left = 0
        ans = 0
        meet = 0

        for right, ch in enumerate(s):
            idx = ord(ch) - 97
            cnt[idx] += 1
            if cnt[idx] == k:
                meet += 1

            while meet > 0:
                left_idx = ord(s[left]) - 97
                cnt[left_idx] -= 1
                if cnt[left_idx] == k - 1:
                    meet -= 1
                left += 1

            ans += left

        return ans

