    def minOperations(self, nums):
        def smallest_prime_factor(x):
            if x <= 1:
                return x
            if x % 2 == 0:
                return 2
            d = 3
            while d * d <= x:
                if x % d == 0:
                    return d
                d += 2
            return x

        n = len(nums)
