        for i in range(n - 2, -1, -1):
            if nums[i] <= nums[i + 1]:
                continue

            spf = smallest_prime_factor(nums[i])
            nums[i] //= nums[i] // spf

            # 等价于 nums[i] = spf
            # 因为一次操作后，一个数会变成它的最小质因子

            if nums[i] > nums[i + 1]:
                return -1

            ans += 1

        return ans

