class Solution:
    def maxScore(self, nums: list[int]) -> int:
        def lcm(a, b):
            return a * b // gcd(a, b)

        def factor_score(arr):
            if not arr:
                return 0
            g = reduce(gcd, arr)
            l = reduce(lcm, arr)
            return g * l

        # Without removing any element
        best = factor_score(nums)

        # Try removing each element
        for i in range(len(nums)):
            sub = nums[:i] + nums[i+1:]
            best = max(best, factor_score(sub))

        return best

