class Solution:
    def minTimeToReach(self, moveTime: List[List[int]]) -> int:
        n, m = len(moveTime), len(moveTime[0])
        dist = [[10**20] * m for _ in range(n)]
        dist[0][0] = 0
        pq = [(0, 0, 0)]  # time, row, col
        dirs = [(1, 0), (-1, 0), (0, 1), (0, -1)]

        while pq:
            t, r, c = heapq.heappop(pq)
            if t != dist[r][c]:
                continue
            if r == n - 1 and c == m - 1:
                return t

            for dr, dc in dirs:
                nr, nc = r + dr, c + dc
                if 0 <= nr < n and 0 <= nc < m:
                    nt = max(t, moveTime[nr][nc]) + 1
                    if nt < dist[nr][nc]:
                        dist[nr][nc] = nt
                        heapq.heappush(pq, (nt, nr, nc))

        return -1

