    def countKReducibleNumbers(self, s: str, k: int) -> int:
        n = len(s)

        if s == "1":
            return 0

        max_bits = n

        steps = [-1] * (max_bits + 1)
        steps[1] = 0
        for x in range2, max_bits + 1):
            steps[x] = 1 + steps[x.bit_count()]

        valid_ones = set()
        for c in range(1, max_bits + 1):
            if 1 + steps[c] <= k:
                valid_ones.add(c)

        if k == 0:
            valid_ones = {1}

        comb = [[0] * (n + 1) for _ in range(n + 1)]
        for i in range(n + 1):
            comb[i][0] = comb[i][i] = 1
            for j in range(1, i):
                comb[i][j] = (comb[i - 1][j - 1] + comb[i - 1][j]) % MOD

        def count_with_ones_limit(target_ones):
            if target_ones < 0:
                return 0
            ans = 0
            ones_used = 0
            remaining_len = n
            for i, ch in enumerate(s):
                remaining_len = n - i - 1
                if ch == '1':
                    need = target_ones - ones_used
                    if 0 <= need <= remaining_len:
                        ans = (ans + comb[remaining_len][need]) % MOD
                    ones_used += 1
                    if ones_used > target_ones:
                        break
            return ans

        ans = 0
        for ones in valid_ones:
            ans = (ans + count_with_ones_limit(ones)) % MOD

        if 1 in valid_ones:
            ans = (ans - 1) % MOD

        return ans

