        if not has_known:
            return 0

        segments = []
        boundary_vals = []

        i = 0
        while i < n:
            if nums[i] != -1:
                i += 1
                continue

            l = i
            while i < n and nums[i] == -1:
                i += 1
            r = i - 1

            left = nums[l - 1] if l - 1 >= 0 and nums[l - 1] != -1 else None
            right = nums[r + 1] if r + 1 < n and nums[r + 1] != -1 else None

            if left is not None:
                boundary_vals.append(left)
            if right is not None:
                boundary_vals.append(right)

            if left is not None and right is not None:
                segments.append((left, right))

        if not boundary_vals:
            return base

        lo = base
        hi = 10**9

        def feasible(D):
            L = min(boundary_vals)
            R = max(boundary_vals)

            x_low = L
            x_high = L + D
            y_low = R - D
            y_high = R

            if x_low > x_high or y_low > y_high:
                return False

            for a, b in segments:
                if abs(a - b) <= D:
                    continue

                ok = False

                if abs(a - x_low) <= D and abs(b - x_low) <= D:
                    ok = True
                if abs(a - y_low) <= D and abs(b - y_low) <= D:
                    ok = True
                if abs(a - x_low) <= D and abs(b - y_low) <= D:
                    ok = True
                if abs(a - y_low) <= D and abs(b - x_low) <= D:
                    ok = True

                if not ok:
                    return False

            return True

        while lo < hi:
            mid = (lo + hi) // 2
            if feasible(mid):
                hi = mid
            else:
                lo = mid + 1

        return lo

