                        b = min(left + m, right + m)
                    else:
                        a = min(left, right) - m
                        b = max(left, right) + m
                elif left is not None:
                    a = left - m
                    b = left + m
                elif right is not None:
                    a = right - m
                    b = right + m
                else:
                    i = j
                    continue

                intervals.append((a, b))
                i = j

            def covers(v):
                for a, b in intervals:
                    if not (a <= v <= b):
                        return False
                return True

            if covers(L) or covers(R):
                return True

            candidates = [L, R]
            for a, b in intervals:
                if L <= a <= R:
                    candidates.append(a)
                if L <= b <= R:
                    candidates.append(b)

            def ok_pair(x, y):
                for a, b in intervals:
                    if not (a <= x <= b or a <= y <= b):
                        return False
                return True

            for x in candidates:
                if ok_pair(x, L) or ok_pair(x, R):
                    return True

            return False

        lo, hi = base, 10**9
        while lo < hi:
            mid = (lo + hi) // 2
            if feasible(mid):
                hi = mid
            else:
                lo = mid + 1
        return lo

Looking at this problem, I need to find optimal values (x, y) to replace all -1s, minimizing the maximum absolute difference between adjacent elements.

**Key Insight:** Binary search on the answer. For a given maximum allowed difference `d`, check if there exist values `x, y` such that all adjacent differences are ≤ `d`.

**Approach:**

1. **Binary search** on the answer `d`.
2. For a given `d`, figure out constraints on `x` and `y`. Each missing element is replaced by either `x` or `y`. Adjacent pairs create constraints.
3. For each pair of adjacent elements, we get constraints. The tricky part is handling segments of consecutive -1s.

**For checking feasibility with a given `d`:**

For consecutive -1 segments, the neighbors on each side (if they exist) constrain what values the -1s can take. Within a run of -1s of length `k`, if both endpoints are known values `a` and `b`, we need to bridge from `a` to `b` in `k+1` steps of size ≤ `d`, using only values from `{x, y}` for the interior.

For a run of missing values between known values `a` and `b`:
- With 1 missing value: it must be within `d` of both `a` and `b`, using `x` or `y`.
- With ≥2 missing values: we can always arrange `x` and `y` alternately, so we need `|x-y| ≤ d`, `a` within `d` of `x` or `y`, and `b` within `d` of `x` or `y`.

For each segment of -1s, we collect intervals of valid `(x, y)` pairs. We need `|x - y| ≤ d`, and for each constraint from a known neighbor, at least one of `x, y` must be within `d` of that neighbor.

Each known neighbor gives a constraint: `x ∈ [v-d, v+d]` OR `y ∈ [v-d, v+d]`. We also need all known-known adjacent pairs to have difference ≤ `d`.

This is a **2-SAT-like** problem, but we can solve it by collecting all the "neighbor values" and trying: for each subset assignment of neighbor constraints to x vs y, find if valid x and y exist. With potentially many neighbors, we use the approach: collect all intervals, and for each pair of constraints, one must go to x and the other to y. We can enumerate: pick x's interval as intersection of some subset, y's as intersection of the rest.

The optimal approach: gather all neighbor values. Sort them. Try assigning each prefix to `x` and suffix to `y`. For each split, `x` must be in the intersection of `[v-d, v+d]` for its group, and similarly for `y`, and `|x-y| ≤ d`.

Here's my solution:

```python
class Solution:
    def minDifference(self, nums):
        n = len(nums)

        def feasible(d):
            # Check all adjacent known-known pairs
            for i in range(n - 1):
                if nums[i] != -1 and nums[i + 1] != -1:
                    if abs(nums[i] - nums[i + 1]) > d:
                        return False

            # Collect all "neighbor" values: known values adjacent to at least one -1
            # For runs of length >= 2, we need |x - y| <= d as extra constraint
            neighbors = []
            need_xy_close = False

            i = 0
            while i < n:
                if nums[i] == -1:
                    j = i
                    while j < n and nums[j] == -1:
                        j += 1
                    run_len = j - i
                    if run_len >= 2:
                        need_xy_close = True
                    if i > 0:
                        neighbors.append(nums[i - 1])
                    if j < n:
                        neighbors.append(nums[j])
                    i = j
                else:
                    i += 1

            if not neighbors:
                return True  # no -1s

            neighbors = sorted(set(neighbors))
            m = len(neighbors)

            # Try all ways to split sorted neighbors into two groups (prefix to x, suffix to y)
            # x must cover [max-d, min+d] of its group, y similarly, and if need_xy_close: |x-y|<=d
            for split in range(m + 1):
                # group_x = neighbors[:split], group_y = neighbors[split:]
                x_lo = x_hi = None
                y_lo = y_hi = None
                if split > 0:
                    x_lo = neighbors[split - 1] - d
                    x_hi = neighbors[0] + d
                if split < m:
                    y_lo = neighbors[m - 1] - d
                    y_hi = neighbors[split] + d

                if x_lo is not None and x_lo > x_hi:
                    continue
                if y_lo is not None and y_lo > y_hi:
                    continue
                if need_xy_close:
                    if x_lo is None:
                        x_lo, x_hi = y_lo, y_hi
                    if y_lo is None:
                        y_lo, y_hi = x_lo, x_hi
                    if x_lo is not None and y_lo is not None:
                        if x_lo - d > y_hi or y_lo - d > x_hi:
                            continue
                return True
            return False

        lo, hi = 0, 2 * 10**9
        while lo < hi:
            mid = (lo + hi) // 2
            if feasible(mid):
                hi = mid
            else:
                lo = mid + 1
        return lo
