class Solution:
    def minDifference(self, nums):
        n = len(nums)
        INF = 10**18

        base = 0
        has_missing = False

        for i in range(n - 1):
            a, b = nums[i], nums[i + 1]
            if a != -1 and b != -1:
                base = max(base, abs(a - b))
            if a == -1 or b == -1:
                has_missing = True

        if not has_missing:
            return base

        mn = INF
        mx = -INF
        for i, v in enumerate(nums):
            if v == -1:
                if i > 0 and nums[i - 1] != -1:
                    mn = min(mn, nums[i - 1])
                    mx = max(mx, nums[i - 1])
                if i + 1 < n and nums[i + 1] != -1:
                    mn = min(mn, nums[i + 1])
                    mx = max(mx, nums[i + 1])

        if mn == INF:
            return 0

        segments = []
        i = 0
        while i < n:
            if nums[i] != -1:
                i += 1
                continue
            l = i
            while i < n and nums[i] == -1:
                i += 1
            r = i - 1

            left = nums[l - 1] if l > 0 and nums[l - 1] != -1 else None
            right = nums[r + 1] if r + 1 < n and nums[r + 1] != -1 else None

            if left is not None and right is not None:
                segments.append((left, right))

        def feasible(d):
            if d < base:
                return False

            low = mx - d
            high = mn + d
            if low > high:
                return False

            events = []
            for a, b in segments:
                l1, r1 = a - d, a + d
                l2, r2 = b - d, b + d

                inter_l = max(l1, l2)
                inter_r = min(r1, r2)
                if inter_l <= inter_r:
                    continue

                if l1 > r2 or l2 > r1:
                    return False

                if r1 < l2:
                    A = (l1, r1)
                    B = (l2, r2)
                else:
                    A = (l2, r2)
                    B = (l1, r1)

                events.append((A[0], 1))
                events.append((A[1] + 1, -1))
                events.append((B[0], 1))
                events.append((B[1] + 1, -1))

            events.append((low, 0))
            events.append((high + 1, 0))
            events.sort()

            cur = 0
            prev = None
            for pos, delta in events:
                if prev is not None and prev < pos:
                    seg_l = max(prev, low)
                    seg_r = min(pos - 1, high)
                    if seg_l <= seg_r:
                        if cur == len(segments):
                            return True
                        if cur == 0:
                            return True
                cur += delta
                prev = pos

            return False

        lo, hi = base, 10**9
        while lo < hi:
            mid = (lo + hi) // 2
            if feasible(mid):
                hi = mid
            else:
                lo = mid + 1
        return lo

class Solution:
    def minimumSumSubarray(self, nums, l, r):
        n = len(nums)
        ans = float('inf')

        prefix = [0] * (n + 1)
        for i in range(n):
            prefix[i + 1] = prefix[i] + nums[i]

        for length in range(l, r + 1):
            for i in range(n - length + 1):
                s = prefix[i + length] - prefix[i]
                if s > 0:
                    ans = min(ans, s)

        return -1 if ans == float('inf') else ans

