class Solution:
    def minArraySum(self, nums, k, op1, op2):
        n = len(nums)
        INF = 10**18

        dp = [[INF] * (op2 + 1) for _ in range(op1 + 1)]
        dp[0][0] = 0

        for x in nums:
            ndp = [[INF] * (op2 + 1) for _ in range(op1 + 1)]

            half = (x + 1) // 2

            op2_only = x - k if x >= k else None

            both12 = None
            if x >= k:
                both12 = (x - k + 1) // 2

            both21 = None
            if half >= k:
                both21 = half - k

            both = None
            if both12 is not None and both21 is not None:
                both = min(both12, both21)
            elif both12 is not None:
                both = both12
            elif both21 is not None:
                both = both21

            for a in range(op1 + 1):
                for b in range(op2 + 1):
                    if dp[a][b] == INF:
                        continue

                    cur = dp[a][b]

                    if cur + x < ndp[a][b]:
                        ndp[a][b] = cur + x

                    if a < op1:
                        val = cur + half
                        if val < ndp[a + 1][b]:
                            ndp[a + 1][b] = val

                    if b < op2 and op2_only is not None:
                        val = cur + op2_only
                        if val < ndp[a][b + 1]:
                            ndp[a][b + 1] = val

                    if a < op1 and b < op2 and both is not None:
                        val = cur + both
                        if val < ndp[a + 1][b + 1]:
                            ndp[a + 1][b + 1] = val

            dp = ndp

        ans = INF
        for a in range(op1 + 1):
            for b in range(op2 + 1):
                if dp[a][b] < ans:
                    ans = dp[a][b]
        return ans

