class Solution:
    def minBitwiseArray(self, nums: List[int]) -> List[int]:
        ans = []

        for p in nums:
            if p == 2:
                ans.append(-1)
                continue

            k = 0
            x = p
            while x & 1:
                k += 1
                x >>= 1

            ans.append(p - (1 << (k - 1)))

        return ans

class Solution:
    def minBitwiseArray(self, nums):
        ans = []
        for p in nums:
            if p == 2:
                ans.append(-1)
                continue

            x = p - 1
            while x > 0 and (x & 1) == 1:
                x >>= 1

            k = 0
            y = p - 1
            while y & 1:
                k += 1
                y >>= 1

            ans.append(p - (1 << (k - 1)))
        return ans

class Solution:
    def maxRemovals(self, source: str, pattern: str, targetIndices: list[int]) -> int:
        n = len(source)
        m = len(pattern)
        removable = [False] * n
        for idx in targetIndices:
            removable[idx] = True

        neg_inf = -10**9
        dp = [neg_inf] * (m + 1)
        dp[0] = 0

        for i in range(n):
            ndp = dp[:]

            if removable[i]:
                for j in range(m + 1):
                    if dp[j] != neg_inf:
                        ndp[j] = max(ndp[j], dp[j] + 1)

            for j in range(m - 1, -1, -1):
                if source[i] == pattern[j] and dp[j] != neg_inf:
                    ndp[j + 1] = max(ndp[j + 1], dp[j])

            dp = ndp

        return dp[m]

