This uses dynamic programming:

- dp[c] = max score possible after the previous day while being in city c
- For each day and destination city:
  - stay there: dp[dest] + stayScore[day][dest]
  - travel from any other city src: dp[src] + travelScore[src][dest]

Since the tourist can start in any city, the initial dp is all 0.

Time complexity: O(k * n^2)
Space complexity: O(n)

class Solution:
    def maxScore(self, n, k, stayScore, travelScore):
        dp = [0] * n

        for day in range(k):
            ndp = [0] * n

            for city in range(n):
                ndp[city] = dp[city] + stayScore[day][city]

            for prev in range(n):
                base = dp[prev]
                row = travelScore[prev]
                for dest in range(n):
                    score = base + row[dest]
                    if score > ndp[dest]:
                        ndp[dest] = score

            dp = ndp

        return max(dp)

class Solution:
    def maxScore(self, n: int, k: int, stayScore: list[list[int]], travelScore: list[list[int]]) -> int:
        # dp[i][c] = max score after day i, ending in city c
        # Initialize: on day 0, tourist can start in any city

        # dp[day][city] = max points achievable up to and including this day, ending at city
        dp = [[0] * n for _ in range(k)]

        # Day 0: tourist starts in some city
        for c in range(n):
            dp[0][c] = stayScore[0][c]  # start in city c and stay

        # Also consider starting in any city and traveling to another on day 0
        # Wait - on day 0, the tourist is already in their starting city.
        # They choose to stay or move. But if it's day 0 and they just arrived (started),
        # staying means they earn stayScore[0][start].
        # Moving means they move from start to dest and earn travelScore[start][dest].

        # Actually, let me reconsider. dp[0][c] = best score ending at city c after day 0.
        # The tourist could have started at city c and stayed: stayScore[0][c]
        # Or started at some other city s and traveled to c: travelScore[s][c]
        for c in range(n):
            for s in range(n):
                if s != c:
                    dp[0][c] = max(dp[0][c], travelScore[s][c])

        for day in range(1, k):
            for c in range(n):
                best = 0
                # Option 1: was in city c yesterday, stay in city c today
                best = max(best, dp[day-1][c] + stayScore[day][c])
                # Option 2: was in some other city s yesterday, travel to c today
                for s in range(n):
                    if s != c:
                        best = max(best, dp[day-1][s] + travelScore[s][c])
                dp[day][c] = best

        return max(dp[k-1])

