class Solution:
    def maxFrequency(self, nums, k, numOperations):
        cnt = Counter(nums)
        vals = sorted(set(nums))

        events = []
        for x in nums:
            events.append((x - k, 1))
            events.append((x + k + 1, -1))
        events.sort()

        cover = {}
        active = 0
        i = 0
        m = len(events)

        for v in vals:
            while i < m and events[i][0] <= v:
                active += events[i][1]
                i += 1
            cover[v] = active

        ans = 0
        for v in vals:
            c = cnt[v]
            reachable = cover[v]
            ans = max(ans, c + min(numOperations, reachable - c))

        if numOperations == 0:
            return ans

        left = 0
        right = 0
        n = len(vals)

        for i, t in enumerate(vals):
            while left < n and vals[left] < t - k:
                left += 1
            while right < n and vals[right] <= t + k:
                right += 1

            reachable_distinct_count = right - left
            total_reachable_elements = 0
            for j in range(left, right):
                total_reachable_elements += cnt[vals[j]]

            ans = max(ans, min(total_reachable_elements, numOperations))

        pref = [0]
        for v in vals:
            pref.append(pref[-1] + cnt[v])

        left = 0
        right = 0
        for t in vals:
            while left < n and vals[left] < t - k:
                left += 1
            while right < n and vals[right] <= t + k:
                right += 1
            total = pref[right] - pref[left]
            ans = max(ans, min(total, cnt[t] + numOperations))

        candidates = sorted(set(vals + [x - k for x in vals] + [x + k for x in vals]))

        return ans

