class Solution:
    def shiftDistance(self, s, t, nextCost, previousCost):
        nnext = [0] * 27
        nprev = [0] * 27

        for i in range(26):
            nnext[i + 1] = nnext[i] + nextCost[i]
            nprev[i + 1] = nprev[i] + previousCost[i]

        total_next_cycle = nnext[26]
        total_prev_cycle = nprev[26]

        def forward_cost(a, b):
            if a <= b:
                return nnext[b] - nnext[a]
            return total_next_cycle - (nnext[a] - nnext[b])

        def backward_cost(a, b):
            if a >= b:
                return nprev[a + 1] - nprev[b + 1]
            return total_prev_cycle - (nprev[b + 1] - nprev[a + 1])

        ans = 0
        for cs, ct in zip(s, t):
            a = ord(cs) - ord('a')
            b = ord(ct) - ord('a')
            ans += min(forward_cost(a, b), backward_cost(a, b))

        return ans

class Solution:
