        n_pref = [0] * 27
        p_pref = [0] * 27

        for i in range(26):
            n_pref[i + 1] = n_pref[i] + nextCost[i]
            p_pref[i + 1] = p_pref[i] + previousCost[i]

        total_next_cycle = n_pref[26]
        total_prev_cycle = p_pref[26]

        def forward_cost(a, b):
            if a <= b:
                return n_pref[b] - n_pref[a]
            return (total_next_cycle - (n_pref[a] - n_pref[b]))

        def backward_cost(a, b):
            if a >= b:
                return p_pref[a + 1] - p_pref[b + 1]
            return (p_pref[a + 1] + (total_prev_cycle - p_pref[b + 1]))

        ans = 0
        base = ord('a')

        for cs, ct in zip(s, t):
            a = ord(cs) - base
            b = ord(ct) - base
            ans += min(forward_cost(a, b), backward_cost(a, b))

        return ans

