            for c in range(lo, hi + 1):
                best = dp[c]
                if c - 1 >= 0:
                    best = max(best, dp[c - 1])
                if c + 1 < n:
                    best = max(best, dp[c + 1])
                if best == neg:
                    continue
                gain = 0 if c == r else fruits[r][c]
                ndp[c] = best + gain
            dp = ndp

        total += max(dp)

        dp = [neg] * n
