- In one operation, you can only reduce the current maximum value(s), because h is valid only when all values greater than h are identical.
- So each distinct value greater than k must be removed one level at a time.
- Therefore, the minimum number of operations is exactly the number of distinct values in nums that are greater than k.

Example:
- nums = [5,2,5,4,5], k = 2
- Distinct values greater than 2 are {4, 5}
- Answer = 2

- nums = [9,7,5,3], k = 1
- Distinct values greater than 1 are {3,5,7,9}
- Answer = 4

class Solution:
    def minOperations(self, nums, k):
        if any(x < k for x in nums):
            return -1
        return len(set(x for x in nums if x > k))

class Solution:
    def findMinimumTime(self, strength, K):
        n = len(strength)
        full = 1 << n

        # dp[mask] = minimum time to break locks in `mask`
        dp = [float('inf')] * full
        dp[0] = 0

        for mask in range(full):
            broken = mask.bit_count()
            x = 1 + broken * K

            for i in range(n):
                if not (mask >> i) & 1:
                    need = (strength[i] + x - 1) // x
                    nxt = mask | (1 << i)
                    dp[nxt] = min(dp[nxt], dp[mask] + need)

        return dp[full - 1]

class Solution:
    def findMinimumTime(self, strength, K):
        n = len(strength)
        full = 1 << n

        ceil_time = [[0] * n for _ in range(n)]
        for broken in range(n):
            x = 1 + broken * K
            for i in range(n):
                ceil_time[broken][i] = (strength[i] + x - 1) // x

        dp = [10**18] * full
        dp[0] = 0

        for mask in range(full):
            broken = mask.bit_count()
            if broken == n:
                continue
            for i in range(n):
                if not (mask >> i) & 1:
                    nxt = mask | (1 << i)
                    dp[nxt] = min(dp[nxt], dp[mask] + ceil_time[broken][i])

        return dp[full - 1]

class Solution:
    def findMinimumTime(self, strength, K):
        from functools import lru_cache

        n = len(strength)

        @lru_cache(None)
        def dfs(mask):
            broken = mask.bit_count()
            if broken == n:
                return 0

            x = 1 + broken * K
            ans = float('inf')

            for i in range(n):
                if not (mask >> i) & 1:
                    minutes = (strength[i] + x - 1) // x
                    ans = min(ans, minutes + dfs(mask | (1 << i)))

            return ans

        return dfs(0)

