class Solution:
    def minOperations(self, n: int, m: int) -> int:
        if self._is_prime(n) or self._is_prime(m):
            return -1

        if n == m:
            return n

        s = str(n)
        t = str(m)
        if len(s) != len(t):
            return -1

        digits = len(s)
        limit = 10 ** digits

        dist = [float('inf')] * limit
        dist[n] = n
        pq = [(n, n)]

        while pq:
            cost, x = heappop(pq)
            if cost != dist[x]:
                continue
            if x == m:
                return cost

            arr = list(str(x).zfill(digits))

            for i in range(digits):
                d = ord(arr[i]) - 48

                if d < 9:
                    arr[i] = chr(ord(arr[i]) + 1)
                    y = int(''.join(arr))
                    if len(str(y)) == digits and not self._is_prime(y):
                        new_cost = cost + y
                        if new_cost < dist[y]:
                            dist[y] = new_cost
                            heappush(pq, (new_cost, y))
                    arr[i] = chr(ord(arr[i]) - 1)

                if d > 0:
                    arr[i] = chr(ord(arr[i]) - 1)
                    y = int(''.join(arr))
                    if len(str(y)) == digits and not self._is_prime(y):
                        new_cost = cost + y
                        if new_cost < dist[y]:
                            dist[y] = new_cost
                            heappush(pq, (new_cost, y))
                    arr[i] = chr(ord(arr[i]) + 1)

        return -1

    def _is_prime(self, x: int) -> bool:
        if x < 2:
            return False
        if x == 2:
            return True
        if x % 2 == 0:
            return False
        d = 3
        while d * d <= x:
            if x % d == 0:
                return False
            d += 2
        return True

