    def countComponents(self, nums, threshold):
        n = len(nums)
        dsu = DSU(n)

        present = {}
        big = 0
        for i, x in enumerate(nums):
            if x <= threshold:
                present[x] = i
            else:
                big += 1

        if not present:
            return n

        vals = sorted(present.keys())
        m = threshold

        divisors = [[] for _ in range(m + 1)]
        for v in vals:
            lim = m // v
            for k in range(1, lim + 1):
                divisors[v * k].append(v)

        for g in range(1, m + 1):
            arr = divisors[g]
            if len(arr) < 2:
                continue
            base = arr[0]
            ib = present[base]
            for x in arr[1:]:
                if base // gcd(base, x) <= m // x:
                    dsu.union(ib, present[x])

        roots = set()
        for i in range(n):
            roots.add(dsu.find(i))
        return len(roots)

