class Solution:
    def countComponents(self, nums, threshold):
        num_set = set(nums)
        # Only values <= threshold can participate in edges
        valid = [x for x in nums if x <= threshold]

        if not valid:
            return len(nums)

        parent = {}

        def find(x):
            while parent[x] != x:
                parent[x] = parent[parent[x]]
                x = parent[x]
            return x

        def union(a, b):
            ra, rb = find(a), find(b)
            if ra != rb:
                parent[ra] = rb

        for x in valid:
            parent[x] = x

        # Mark which multiples exist
        present = [False] * (threshold + 1)
        for x in valid:
            present[x] = True

        for d in range(1, threshold + 1):
            # Collect all multiples of d that are in nums and <= threshold
            first = -1
            for multiple in range(d, threshold + 1, d):
                if present[multiple]:
                    if first == -1:
                        first = multiple
                    else:
                        union(first, multiple)

        # Count components: components among valid + isolated nodes (nums > threshold)
        components = len(set(find(x) for x in valid))
        isolated = sum(1 for x in nums if x > threshold)

        return components + isolated

