class Solution:
    def countComponents(self, nums, threshold):
        num_set = set(nums)
        n = len(nums)

        parent = {x: x for x in nums}
        rank = {x: 0 for x in nums}

        def find(x):
            while parent[x] != x:
                parent[x] = parent[parent[x]]
                x = parent[x]
            return x

        def union(a, b):
            a, b = find(a), find(b)
            if a == b:
                return
            if rank[a] < rank[b]:
                a, b = b, a
            parent[b] = a
            if rank[a] == rank[b]:
                rank[a] += 1

        first = [0] * (threshold + 1)

        for val in nums:
            if val > threshold:
                continue
            for m in range(val, threshold + 1, val):
                if first[m]:
                    union(val, first[m])
                else:
                    first[m] = val

        components = len(set(find(x) for x in nums))
        return components
