class DSU:
    def __init__(self, n: int):
        self.parent = list(range(n))
        self.rank = [0] * n
        self.count = n

    def find(self, x: int) -> int:
        while self.parent[x] != x:
            self.parent[x] = self.parent[self.parent[x]]
            x = self.parent[x]
        return x

    def union(self, a: int, b: int) -> bool:
        ra = self.find(a)
        rb = self.find(b)
        if ra == rb:
            return False
        if self.rank[ra] < self.rank[rb]:
            ra, rb = rb, ra
        self.parent[rb] = ra
        if self.rank[ra] == self.rank[rb]:
            self.rank[ra] += 1
        self.count -= 1
        return True

class Solution:
    def countComponents(self, nums: List[int], threshold: int) -> int:
        n = len(nums)
        dsu = DSU(n)

        value_to_index = {}
        small_values = []
        for i, x in enumerate(nums):
            if x <= threshold:
                value_to_index[x] = i
                small_values.append(x)

        # Any value > threshold cannot connect to anything:
        # lcm(a, b) >= max(a, b) > threshold.
        if not small_values:
            return n

        present = [False] * (threshold + 1)
        for x in small_values:
            present[x] = True

        # For each possible gcd-like hub g, all present multiples of g
        # with value <= threshold and pairwise product condition through g
        # can be connected whenever for numbers a=g*x and b=g*y:
        # lcm(a,b) = g*x*y when gcd(x,y)=1, but checking all pairs is too hard.
        #
        # Better viewpoint:
        # If two numbers u and v satisfy lcm(u,v) <= threshold, then letting
        # L = lcm(u,v), both u and v divide L.
        # So if we process each L <= threshold and union all present divisors
        # of L that appear in nums, then every valid edge is added.
        #
        # Total work is sum of divisor-enumeration over L=1..threshold,
        # which is about threshold log threshold.

        divisors_present = [[] for _ in range(threshold + 1)]
        for x in small_values:
            for multiple in range(x, threshold + 1, x):
                divisors_present[multiple].append(x)

        for L in range(1, threshold + 1):
            vals = divisors_present[L]
            if len(vals) >= 2:
                base_idx = value_to_index[vals[0]]
                for v in vals[1:]:
                    dsu.union(base_idx, value_to_index[v])

        return dsu.count

