class Solution:
    def maxAmount(self, initialCurrency, pairs1, rates1, pairs2, rates2):
        def build_graph(pairs, rates):
            graph = {}
            for (a, b), r in zip(pairs, rates):
                if a not in graph:
                    graph[a] = []
                if b not in graph:
                    graph[b] = []
                graph[a].append((b, r))
                graph[b].append((a, 1.0 / r))
            return graph

        def get_values_from(start, graph):
            values = {start: 1.0}
            stack = [start]
            while stack:
                cur = stack.pop()
                for nxt, rate in graph.get(cur, []):
                    if nxt not in values:
                        values[nxt] = values[cur] * rate
                        stack.append(nxt)
            return values

        g1 = build_graph(pairs1, rates1)
        g2 = build_graph(pairs2, rates2)

        day1_amounts = get_values_from(initialCurrency, g1)

        answer = 1.0
        for currency, amt_after_day1 in day1_amounts.items():
            day2_values = get_values_from(currency, g2)
            if initialCurrency in day2_values:
                answer = max(answer, amt_after_day1 * day2_values[initialCurrency])

        return answer

