from typing import List

class Solution:
    def maxAmount(self, initialCurrency: str, pairs1: List[List[str]], rates1: List[float], pairs2: List[List[str]], rates2: List[float]) -> float:
        def build_graph(pairs, rates):
            g = defaultdict(list)
            for (a, b), r in zip(pairs, rates):
                g[a].append((b, r))
                g[b].append((a, 1.0 / r))
            return g

        def reachable_amounts(start, graph):
            amounts = {start: 1.0}
            q = deque([start])
            while q:
                cur = q.popleft()
                for nxt, rate in graph[cur]:
                    if nxt not in amounts:
                        amounts[nxt] = amounts[cur] * rate
                        q.append(nxt)
            return amounts

        g1 = build_graph(pairs1, rates1)
        g2 = build_graph(pairs2, rates2)

        day1_amounts = reachable_amounts(initialCurrency, g1)

        best_back_to_initial = {}
        for currency in day1_amounts:
            amounts_from_currency = reachable_amounts(currency, g2)
            best_back_to_initial[currency] = amounts_from_currency.get(initialCurrency, 0.0)

        ans = 1.0
        for currency, amt1 in day1_amounts.items():
            ans = max(ans, amt1 * best_back_to_initial[currency])

        return ans

