class Solution:
    def beautifulSplits(self, nums):
        n = len(nums)
        if n < 3:
            return 0

        # lcp[i][j] = longest common prefix length of nums[i:] and nums[j:]
        lcp = [[0] * (n + 1) for _ in range(n + 1)]
        for i in range(n - 1, -1, -1):
            row = lcp[i]
            next_row = lcp[i + 1]
            ai = nums[i]
            for j in range(n - 1, -1, -1):
                if ai == nums[j]:
                    row[j] = next_row[j + 1] + 1

        ans = 0

        # Split points:
        # nums1 = nums[0:i]
        # nums2 = nums[i:j]
        # nums3 = nums[j:n]
        # where 1 <= i < j <= n-1
        for i in range(1, n - 1):
            for j in range(i + 1, n):
                len1 = i
                len2 = j - i
                len3 = n - j

                ok = False

                # nums1 is a prefix of nums2
                if len1 <= len2 and lcp[0][i] >= len1:
                    ok = True

                # nums2 is a prefix of nums3
                elif len2 <= len3 and lcp[i][j] >= len2:
                    ok = True

                if ok:
                    ans += 1

        return ans

