class Solution:
    def countPathsWithXorValue(self, grid, k):
        MOD = 10**9 + 7
        m, n = len(grid), len(grid[0])

        prev = [[0] * 16 for _ in range(n)]

        for i in range(m):
            curr = [[0] * 16 for _ in range(n)]
            for j in range(n):
                val = grid[i][j]

                if i == 0 and j == 0:
                    curr[j][val] = 1
                    continue

                if i > 0:
                    for x in range(16):
                        cnt = prev[j][x]
                        if cnt:
                            curr[j][x ^ val] = (curr[j][x ^ val] + cnt) % MOD

                if j > 0:
                    for x in range(16):
                        cnt = curr[j - 1][x]
                        if cnt:
                            curr[j][x ^ val] = (curr[j][x ^ val] + cnt) % MOD

            prev = curr

        return prev[n - 1][k]

