    def countPathsWithXorValue(self, grid: list[list[int]], k: int) -> int:
        MOD = 10**9 + 7
        m, n = len(grid), len(grid[0])

        # dp[i][j][x] = number of paths from (0,0) to (i,j) with XOR value x
        # Since grid values < 16 and k < 16, XOR values range from 0 to 15
        dp = [[[0] * 16 for _ in range(n)] for _ in range(m)]

        dp[0][0][grid[0][0]] = 1

        for i in range(m):
            for j in range(n):
                if i == 0 and j == 0:
                    continue
                for x in range(16):
                    val = 0
                    # From top
                    if i > 0:
                        # We need x ^ grid[i][j] = prev_xor => prev_xor = x ^ grid[i][j]
                        prev_xor = x ^ grid[i][j]
                        val += dp[i-1][j][prev_xor]
                    # From left
                    if j > 0:
                        prev_xor = x ^ grid[i][j]
                        val += dp[i][j-1][prev_xor]
                    dp[i][j][x] = val % MOD

        return dp[m-1][n-1][k]

