    def checkValidCuts(self, n, rectangles):
        def can_split(intervals):
            intervals.sort()
            groups = 0
            cur_end = -1

            for start, end in intervals:
                if start >= cur_end:
                    groups += 1
                    cur_end = end
                else:
                    if end > cur_end:
                        cur_end = end

            return groups >= 3

        x_intervals = [(x1, x2) for x1, y1, x2, y2 in rectangles]
        y_intervals = [(y1, y2) for x1, y1, x2, y2 in rectangles]

        return can_split(x_intervals) or can_split(y_intervals)

