    def checkValidCuts(self, n: int, rectangles: list[list[int]]) -> bool:
        def canCut(intervals):
            # Sort intervals by start, then by end
            intervals.sort()
            # Count how many non-overlapping groups we can form
            groups = 0
            max_end = 0
            for start, end in intervals:
                if start >= max_end and max_end > 0:
                    groups += 1
                max_end = max(max_end, end)
            groups += 1  # last group
            return groups >= 3

        # Try vertical cuts: project onto x-axis
        x_intervals = [(r[0], r[2]) for r in rectangles]
        if canCut(x_intervals):
            return True

        # Try horizontal cuts: project onto y-axis
        y_intervals = [(r[1], r[3]) for r in rectangles]
        if canCut(y_intervals):
            return True

        return False

