class Solution:
    def subsequencesWithMiddleMode(self, nums):
        MOD = 10**9 + 7
        n = len(nums)

        def c2(x):
            return x * (x - 1) // 2 if x >= 2 else 0

        total = 0

        left = {}
        right = {}
        for x in nums:
            right[x] = right.get(x, 0) + 1

        for i, x in enumerate(nums):
            right[x] -= 1
            if right[x] == 0:
                del right[x]

            L = i
            R = n - 1 - i
            if L >= 2 and R >= 2:
                lx = left.get(x, 0)
                rx = right.get(x, 0)

                # Case 1: x appears 5 times
                total += c2(lx) * c2(rx)

                # Case 2: x appears 4 times
                total += c2(lx) * rx * (R - rx)
                total += lx * (L - lx) * c2(rx)

                # Case 3: x appears 3 times
                # Need one x on each side, plus two non-x values not equal to each other
                nonx_left = L - lx
                nonx_right = R - rx
                all_pairs = nonx_left * nonx_right

                same_nonx = 0
                if nonx_left and nonx_right:
                    if len(left) < len(right):
                        for v, cl in left.items():
                            if v != x:
                                same_nonx += cl * right.get(v, 0)
                    else:
                        for v, cr in right.items():
                            if v != x:
                                same_nonx += cr * left.get(v, 0)

                diff_nonx = all_pairs - same_nonx
                total += lx * rx * diff_nonx

                # Case 4: x appears exactly 2 times
                # Need one x on one side, none on the other.
                # The other 3 picked values must all be distinct and distinct from x.
                # Also the side with 2 picks must avoid equal pair.
                if lx:
                    # pick 1 x from left, 0 x from right, 2 non-x from right, 1 non-x from left
                    total_nonx_left = nonx_left
                    total_pairs_right = c2(nonx_right)

                    sum_right_same_as_left = 0
                    sum_right_pairs_equal = 0

                    for v, cl in left.items():
                        if v == x:
                            continue
                        rv = right.get(v, 0)
                        sum_right_same_as_left += cl * rv * (nonx_right - rv)

                    for v, rv in right.items():
                        if v != x:
                            sum_right_pairs_equal += c2(rv)

                    valid = total_nonx_left * total_pairs_right - sum_right_same_as_left - nonx_left * sum_right_pairs_equal
                    total += lx * valid

                if rx:
                    # symmetric
                    total_nonx_right = nonx_right
                    total_pairs_left = c2(nonx_left)

                    sum_left_same_as_right = 0
                    sum_left_pairs_equal = 0

                    for v, cr in right.items():
                        if v == x:
                            continue
                        lv = left.get(v, 0)
                        sum_left_same_as_right += cr * lv * (nonx_left - lv)

                    for v, lv in left.items():
                        if v != x:
                            sum_left_pairs_equal += c2(lv)

                    valid = total_nonx_right * total_pairs_left - sum_left_same_as_right - nonx_right * sum_left_pairs_equal
                    total += rx * valid

            left[x] = left.get(x, 0) + 1

        return total % MOD

