class Solution:
    def maxLength(self, nums):
        def lcm(a, b):
            return a // gcd(a, b) * b

        n = len(nums)
        ans = 1

        for i in range(n):
            prod = 1
            g = 0
            l = 1

            for j in range(i, n):
                x = nums[j]
                prod *= x
                g = x if g == 0 else gcd(g, x)
                l = lcm(l, x)

                if prod == g * l:
                    ans = max(ans, j - i + 1)

        return ans

