from math import gcd, prod
from functools import reduce

class Solution:
    def maxLength(self, nums: list[int]) -> int:
        def lcm(a, b):
            return a * b // gcd(a, b)

        def array_lcm(arr):
            return reduce(lcm, arr)

        def array_gcd(arr):
            return reduce(gcd, arr)

        n = len(nums)
        best = 1

        for i in range(n):
            for j in range(i + 1, n + 1):
                sub = nums[i:j]
                p = prod(sub)
                g = array_gcd(sub)
                l = array_lcm(sub)
                if p == l * g:
                    best = max(best, j - i)

        return best

