    def calculateScore(self, s: str) -> int:
        # For each character, maintain a stack of unmarked indices
        # The mirror of character c is: 'a' + 'z' - c
        # We want the closest unmarked j < i, so we use a stack (last element is closest)

        from collections import defaultdict

        stacks = defaultdict(list)  # char -> list of unmarked indices (in order)
        score = 0

        for i, c in enumerate(s):
            mirror = chr(ord('a') + ord('z') - ord(c))
            if stacks[mirror]:
                j = stacks[mirror].pop()  # closest (largest index < i) is at the end
                score += i - j
            else:
                stacks[c].append(i)

        return score

