                R = L + k - 1

                while j < n and ends[j] < R:
                    j += 1

                total = 0
                if j > i:
                    total += prefix[j] - prefix[i]

                if j < n and starts[j] <= R:
                    total += (R - starts[j] + 1) * vals[j]

