    def hasMatch(self, s: str, p: str) -> bool:
        i = p.index('*')
        left = p[:i]
        right = p[i + 1:]

        if not left and not right:
            return True

        n = len(s)
        len_left = len(left)
        len_right = len(right)

        for start in range(n):
            if start + len_left > n:
                break
            if s[start:start + len_left] != left:
                continue

            min_end = start + len_left
            max_right_start = n - len_right

            for rstart in range(min_end, max_right_start + 1):
                if s[rstart:rstart + len_right] == right:
                    if rstart + len_right - start > 0:
                        return True

        return False

