class Solution:
    def longestSubsequence(self, nums):
        MAXV = 300

        # dp_end[v][d] = best length of a subsequence ending with value v
        # whose last absolute difference is exactly d
        dp_end = [[0] * (MAXV + 1) for _ in range(MAXV + 1)]

        # pref[v][d] = max(dp_end[v][k] for k >= d)
        # lets us query best subsequence ending at value v with last diff >= d
        pref = [[0] * (MAXV + 2) for _ in range(MAXV + 1)]

        ans = 1

        for x in nums:
            best_for_diff = [0] * (MAXV + 1)

            # Try extending any previous subsequence ending with value pv
            for pv in range(1, MAXV + 1):
                d = abs(x - pv)
                # extend a subsequence whose previous last diff >= d
                cand = pref[pv][d] + 1
                # or start a new length-2 subsequence [pv, x]
                if cand < 2:
                    cand = 2
                if cand > best_for_diff[d]:
                    best_for_diff[d] = cand

            # Apply updates for subsequences ending at x
            changed = False
            for d in range(MAXV + 1):
                if best_for_diff[d] > dp_end[x][d]:
                    dp_end[x][d] = best_for_diff[d]
                    changed = True
                    if best_for_diff[d] > ans:
                        ans = best_for_diff[d]

            # Rebuild suffix maxima for value x if anything changed
            if changed:
                row = dp_end[x]
                p = pref[x]
                p[MAXV] = row[MAXV]
                for d in range(MAXV - 1, -1, -1):
                    if row[d] > p[d + 1]:
                        p[d] = row[d]
                    else:
                        p[d] = p[d + 1]

        return ans

class Solution:
    def maxSubarraySum(self, nums):
        vals = list(set(nums))
        base = self._kadane(nums)
        ans = base

        for x in vals:
            filtered = []
            for v in nums:
                if v != x:
                    filtered.append(v)
            if filtered:
                ans = max(ans, self._kadane(filtered))

        return ans

    def _kadane(self, arr):
        best = cur = arr[0]
        for i in range(1, len(arr)):
            cur = max(arr[i], cur + arr[i])
            best = max(best, cur)
        return best

class Solution:
    def maxSubarraySum(self, nums):
        vals = sorted(set(nums))
        idx = {v: i for i, v in enumerate(vals)}
        m = len(vals)

        size = 1
        while size < m:
            size <<= 1

        NEG = -10**30
        tree = [(NEG, NEG, NEG, 0) for _ in range(2 * size)]

        def merge(a, b):
            best1 = a[0] if a[0] >= b[0] else b[0]
            best2 = a[1] if a[1] >= b[1] else b[1]
            pref = a[2] if a[2] >= a[3] + b[2] else a[3] + b[2]
            total = a[3] + b[3]
            return (best1, best2, pref, total)

        def apply(pos, val):
            i = pos + size
            tree[i] = (val, 0, max(val, 0), val)
            i >>= 1
            while i:
                tree[i] = merge(tree[i << 1], tree[i << 1 | 1])
                i >>= 1

        ans = max(nums)
        cur = 0

        for x in nums:
            cur = max(x, cur + x)
            if cur > ans:
                ans = cur

        for x in nums:
            apply(idx[x], x)

        root = tree[1]
        if root[1] > ans:
            ans = root[1]

        return ans

