        n = len(nums)

        best_no_delete = nums[0]
        cur = nums[0]
        for i in range(1, n):
            cur = max(nums[i], cur + nums[i])
            if cur > best_no_delete:
                best_no_delete = cur

        vals = set(nums)
        ans = best_no_delete

        for x in vals:
            if len(vals) == 1 and n == nums.count(x):
                continue

            started = False
            cur = 0
            best = -10**30
            kept = 0

            for v in nums:
                if v == x:
                    continue
                kept += 1
                if not started:
                    cur = v
                    best = v
                    started = True
                else:
                    cur = max(v, cur + v)
                    if cur > best:
                        best = cur

            if kept > 0 and best > ans:
                ans = best

        return ans

