    def maximumAmount(self, coins: list[list[int]]) -> int:
        m = len(coins)
        n = len(coins[0])

        # dp[i][j][k] = max coins reaching (i,j) with k neutralizations remaining
        NEG_INF = float('-inf')

        # Initialize dp
        dp = [[[NEG_INF] * 3 for _ in range(n)] for _ in range(m)]

        # Base case: starting cell (0,0)
        val = coins[0][0]
        dp[0][0][2] = val  # no neutralization used
        if val < 0:
            dp[0][0][1] = 0  # neutralize (0,0), 1 neutralization remaining

        for i in range(m):
            for j in range(n):
                if i == 0 and j == 0:
                    continue
                val = coins[i][j]
                for k in range(3):  # k neutralizations remaining
                    best = NEG_INF
                    # Come from above
                    if i > 0:
                        best = max(best, dp[i-1][j][k])
                    # Come from left
                    if j > 0:
                        best = max(best, dp[i][j-1][k])

                    if best == NEG_INF:
                        # Can't reach (i,j) with k neutralizations remaining without using one here
                        dp[i][j][k] = NEG_INF
                    else:
                        # Option 1: don't neutralize this cell
                        dp[i][j][k] = best + val

                    # Option 2: neutralize this cell (only if val < 0 and k+1 <= 2)
                    if val < 0 and k + 1 <= 2:
                        best2 = NEG_INF
                        if i > 0:
                            best2 = max(best2, dp[i-1][j][k+1])
                        if j > 0:
                            best2 = max(best2, dp[i][j-1][k+1])
                        if best2 != NEG_INF:
                            dp[i][j][k] = max(dp[i][j][k], best2)  # neutralize: add 0 instead of val

        return max(dp[m-1][n-1][k] for k in range(3))

