    def minMaxWeight(self, n, edges, threshold):
        if n == 1:
            return 0

        rev = [[] for _ in range(n)]
        max_w = 0
        for a, b, w in edges:
            rev[b].append((a, w))
            if w > max_w:
                max_w = w

        def can(limit):
            seen = [False] * n
            stack = [0]
            seen[0] = True
            cnt = 1

            while stack:
                u = stack.pop()
                for v, w in rev[u]:
                    if w <= limit and not seen[v]:
                        seen[v] = True
                        cnt += 1
                        stack.append(v)

            return cnt == n

        if not can(max_w):
            return -1

        lo, hi = 1, max_w
        while lo < hi:
            mid = (lo + hi) // 2
            if can(mid):
                hi = mid
            else:
                lo = mid + 1
        return lo

