    def countNonDecreasingSubarrays(self, nums, k):
        n = len(nums)

        nxt = [n] * n
        st = []
        for i in range(n - 1, -1, -1):
            while st and nums[st[-1]] <= nums[i]:
                st.pop()
            nxt[i] = st[-1] if st else n
            st.append(i)

        prefix = [0] * (n + 1)
        for i in range(n):
            prefix[i + 1] = prefix[i] + nums[i]

        total = 0
        j = 0
        cost = 0
        segments = []
        head = 0

        def segment_sum(l, r):
            return prefix[r] - prefix[l]

        for i in range(n):
            if j < i:
                j = i
                cost = 0
                segments = []
                head = 0

            while j < n:
                add = 0
                cur = j
                while True:
                    while head < len(segments) and segments[head][1] <= cur:
                        head += 1
                    if head == len(segments):
                        break
                    s, e, h = segments[head]
                    add += (min(e, j) - cur) * (h - nums[j])
                    cur = min(e, j)
                    if cur == j:
                        break

                if cost + add > k:
                    break

                cost += add

                start = j
                end = nxt[j]
                while len(segments) > head and segments[-1][2] <= nums[j]:
                    start = segments[-1][0]
                    segments.pop()
                segments.append((start, end, nums[j]))
                j += 1

            total += j - i

            if i == j:
                j += 1
                continue

            while head < len(segments) and segments[head][1] <= i:
                head += 1

            if head < len(segments):
                s, e, h = segments[head]
                cost -= h - nums[i]
                if i + 1 == e:
                    head += 1

        return total

