class Solution:
    def minMaxSums(self, nums, k):
        MOD = 10**9 + 7
        nums.sort()
        n = len(nums)

        if k == 1:
            return (2 * sum(nums)) % MOD

        fact = [1] * (n + 1)
        invfact = [1] * (n + 1)
        for i in range(1, n + 1):
            fact[i] = fact[i - 1] * i % MOD

        invfact[n] = pow(fact[n], MOD - 2, MOD)
        for i in range(n, 0, -1):
            invfact[i - 1] = invfact[i] * i % MOD

        def comb(a, b):
            if b < 0 or b > a:
                return 0
            return fact[a] * invfact[b] % MOD * invfact[a - b] % MOD

        limit = min(k - 1, n - 1)

        ways = [0] * n
        s = 0
        for i in range(n):
            upto = min(limit, i)
            total = 0
            for t in range(upto + 1):
                total += comb(i, t)
            ways[i] = total % MOD

        ans = 0
        for i, x in enumerate(nums):
            ans = (ans + x * ways[i]) % MOD
            ans = (ans + x * ways[n - 1 - i]) % MOD

        return ans % MOD

class Solution:
    def minMaxSums(self, nums, k):
        MOD = 10**9 + 7
        nums.sort()
        n = len(nums)

        if k == 0:
            return 0

        m = k - 1

        # ways[t] = sum_{j=0..m} C(t, j)
        # We compute this for t = 0..n-1 in O(n * k) using:
        # ways[t+1] = 2*ways[t] - C(t, m)
        ways = [0] * n
        ways[0] = 1

        if m >= 0:
            comb_m = 1 if m == 0 else 0  # C(0, m)

        for t in range(n - 1):
            ways[t + 1] = (2 * ways[t] - comb_m) % MOD

            if m >= 0:
                # Update comb_m from C(t, m) to C(t+1, m)
                if m == 0:
                    comb_m = 1
                elif t + 1 < m:
                    comb_m = 0
                elif t + 1 == m:
                    comb_m = 1
                else:
                    comb_m = comb_m * (t + 1) % MOD
                    comb_m = comb_m * pow(t + 1 - m, MOD - 2, MOD) % MOD

        ans = 0
        for i, x in enumerate(nums):
            cnt = (ways[i] + ways[n - 1 - i]) % MOD
            ans = (ans + x % MOD * cnt) % MOD

        return ans

class Solution:
    def minCost(self, n, cost):
        INF = 10**30

        # dp[pl][pr] = minimum cost after processing pairs up to current layer,
        # where:
        #   pl = color of the last painted house on the left side
        #   pr = color of the last painted house on the right side
        #
        # We process symmetric pairs:
        # (0, n-1), (1, n-2), ..., (n/2-1, n/2)
        #
        # For each pair (i, j), choose colors (cl, cr) such that:
        #   1) cl != cr                  (equidistant-from-ends constraint)
        #   2) cl != previous left color (adjacent on left)
        #   3) cr != previous right color(adjacent on right)

        dp = [[INF] * 3 for _ in range(3)]

        # First pair: only need cl != cr
        i, j = 0, n - 1
        for cl in range(3):
            for cr in range(3):
                if cl != cr:
                    dp[cl][cr] = cost[i][cl] + cost[j][cr]

        # Remaining pairs
        for i in range(1, n // 2):
            j = n - 1 - i
            ndp = [[INF] * 3 for _ in range(3)]

            for pl in range(3):
                for pr in range(3):
                    if dp[pl][pr] == INF:
                        continue
                    base = dp[pl][pr]

                    for cl in range(3):
                        if cl == pl:
                            continue
                        for cr in range(3):
                            if cr == pr or cl == cr:
                                continue
                            val = base + cost[i][cl] + cost[j][cr]
                            if val < ndp[cl][cr]:
                                ndp[cl][cr] = val

            dp = ndp

        ans = INF
        for a in range(3):
            for b in range(3):
                if dp[a][b] < ans:
                    ans = dp[a][b]
        return ans

