    def minCost(self, n, cost):
        INF = 10**30

        # dp[a][b]:
        # 已处理到第 i 对房子（i, n-1-i）时，
        # 左侧当前房子颜色为 a，右侧当前房子颜色为 b 的最小代价
        # 其中还需满足：
        # 1. 每一对内部 a != b
        # 2. 左侧相邻不同（与上一对左房子不同）
        # 3. 右侧相邻不同（与上一对右房子不同）
        m = n // 2

        dp = [[INF] * 3 for _ in range(3)]

        # 初始化第 0 对：(0, n-1)
        for a in range(3):
            for b in range(3):
                if a != b:
                    dp[a][b] = cost[0][a] + cost[n - 1][b]

        # 逐对转移
        for i in range(1, m):
            ndp = [[INF] * 3 for _ in range(3)]
            left_idx = i
            right_idx = n - 1 - i

            for pa in range(3):
                for pb in range(3):
                    if dp[pa][pb] == INF:
                        continue
                    base = dp[pa][pb]

                    for a in range(3):
                        if a == pa:
