                for i in range(n - 1, -1, -1):
                    while stack and nums[stack[-1]] < nums[i]:
                        stack.pop()
                    nxt[i] = stack[-1] if stack else n
                    stack.append(i)

            def count_pairs(L, R, k):
                a = min(L, k)
                low = max(1, k - R + 1)
                if low > a:
                    return L * R
                m = low - 1
                total1 = m * R
                cnt2 = a - m
