class Solution:
    def countSubstrings(self, s: str) -> int:
        n = len(s)
        ans = 0

        # dp[d][r]: for current position, number of substrings ending here
        # whose value modulo d equals r
        dp = {d: [0] * d for d in range(1, 10)}

        for ch in s:
            x = ord(ch) - ord('0')
            new_dp = {}

            for d in range(1, 10):
                arr = [0] * d

                # extend previous substrings
                prev = dp[d]
                for r in range(d):
                    cnt = prev[r]
                    if cnt:
                        nr = (r * 10 + x) % d
                        arr[nr] += cnt

                # start new substring at current position
                arr[x % d] += 1
                new_dp[d] = arr

            if x != 0:
                ans += new_dp[x][0]

            dp = new_dp

        return ans

class Solution:
    def maxScore(self, points, m):
        n = len(points)

        def can(x):
            need = [0] * n
            for i in range(n):
                need[i] = (x + points[i] - 1) // points[i]

            if need[0] == 0:
                return True

            moves = 0
            prev = 0

            for i in range(n - 1):
                cur = max(need[i], prev)
                moves += 2 * cur - prev
                if moves > m:
                    return False
                prev = cur
                need[i + 1] = max(0, need[i + 1] - cur)

            moves += need[-1]
            return moves <= m

        lo, hi = 0, max(points) * m
        while lo < hi:
            mid = (lo + hi + 1) // 2
            if can(mid):
                lo = mid
            else:
                hi = mid - 1
        return lo

