    def maxScore(self, points, m):
        n = len(points)

        if m < n:
            return 0

        def can(x):
            moves = 0
            prev = 0

            for i in range(n):
                need = (x + points[i] - 1) // points[i]

                if i == n - 1:
                    extra = max(0, need - prev)
                    moves += extra
                    return moves <= m

                if prev >= need:
                    curr = 0
                else:
                    curr = need - prev
                    moves += 2 * curr - 1
                    if moves > m:
                        return False

                prev = curr

            return moves <= m

        left, right = 0, max(points) * m

        while left < right:
            mid = (left + right + 1) // 2
            if can(mid):
                left = mid
            else:
                right = mid - 1

        return left

