    def maxSubstringLength(self, s: str, k: int) -> bool:
        if k == 0:
            return True

        n = len(s)
        first = [-1] * 26
        last = [-1] * 26

        for i, ch in enumerate(s):
            x = ord(ch) - 97
            if first[x] == -1:
                first[x] = i
            last[x] = i

        intervals = []

        for c in range(26):
            if first[c] == -1:
                continue

            l = first[c]
            r = last[c]
            j = l
            valid = True

            while j <= r:
                x = ord(s[j]) - 97
                if first[x] < l:
                    valid = False
                    break
                if last[x] > r:
                    r = last[x]
                j += 1

            if valid and not (l == 0 and r == n - 1):
                intervals.append((l, r))

        intervals.sort(key=lambda x: x[1])

        count = 0
        prev_end = -1
        for l, r in intervals:
            if l > prev_end:
                count += 1
                prev_end = r
                if count >= k:
                    return True

        return False

