class Solution:
    def lenOfVDiagonal(self, grid):
        n = len(grid)
        m = len(grid[0])

        dirs = [(1, 1), (1, -1), (-1, -1), (-1, 1)]
        cw = [1, 2, 3, 0]

        # dp[d][p][r][c]:
        # maximum length starting at (r,c), moving in direction d,
        # where grid[r][c] must equal:
        #   2 if p == 0
        #   0 if p == 1
        # and then alternating afterward.
        dp = [[[[0] * m for _ in range(n)] for _ in range(2)] for _ in range(4)]

        for d, (dr, dc) in enumerate(dirs):
            r_range = range(n - 1, -1, -1) if dr == 1 else range(n)
            c_range = range(m - 1, -1, -1) if dc == 1 else range(m)

            for r in r_range:
                for c in c_range:
                    nr, nc = r + dr, c + dc
                    for p in range(2):
                        need = 2 if p == 0 else 0
                        if grid[r][c] != need:
                            dp[d][p][r][c] = 0
                        else:
                            val = 1
                            if 0 <= nr < n and 0 <= nc < m:
                                val += dp[d][p ^ 1][nr][nc]
                            dp[d][p][r][c] = val

        ans = 0

        for r in range(n):
            for c in range(m):
                if grid[r][c] != 1:
                    continue

                ans = max(ans, 1)

                for d, (dr, dc) in enumerate(dirs):
                    nr, nc = r + dr, c + dc
                    if not (0 <= nr < n and 0 <= nc < m):
                        continue
                    if grid[nr][nc] != 2:
                        continue

                    # No turn
                    straight = 1 + dp[d][0][nr][nc]
                    if straight > ans:
                        ans = straight

                    # One clockwise turn at some point on the first leg
                    turn_dir = cw[d]
                    cr, cc = nr, nc
                    step = 1  # number of cells after the starting 1 already included on first leg

                    while 0 <= cr < n and 0 <= cc < m:
                        expected = 2 if step % 2 == 1 else 0
                        if grid[cr][cc] != expected:
                            break

                        # After consuming 'step' cells beyond the initial 1,
                        # next expected value on turned leg:
                        next_parity = step % 2  # 1->expect 0, 0->expect 2
                        tdr, tdc = dirs[turn_dir]
                        tr, tc = cr + tdr, cc + tdc

                        turned = 1 + step
                        if 0 <= tr < n and 0 <= tc < m:
                            turned += dp[turn_dir][next_parity][tr][tc]

                        if turned > ans:
                            ans = turned

                        cr += dr
                        cc += dc
                        step += 1

        return ans

class Solution:
    def lenOfVDiagonal(self, grid):
        n, m = len(grid), len(grid[0])

        dirs = [(1, 1), (1, -1), (-1, -1), (-1, 1)]
        cw = [1, 2, 3, 0]

        # dp[d][p][r][c]:
        # maximum length starting at (r,c), moving in direction d,
        # where grid[r][c] must equal expected value:
        # p=0 => expect 2 at (r,c)
        # p=1 => expect 0 at (r,c)
        #
        # Length counts cells from (r,c) onward along that direction.
        dp = [[[[0] * m for _ in range(n)] for _ in range(2)] for _ in range(4)]

        for d, (dr, dc) in enumerate(dirs):
            if dr == 1:
                r_range = range(n - 1, -1, -1)
            else:
                r_range = range(n)

            if dc == 1:
                c_range = range(m - 1, -1, -1)
            else:
                c_range = range(m)

            for r in r_range:
                for c in c_range:
                    nr, nc = r + dr, c + dc

                    if grid[r][c] == 2:
                        dp[d][0][r][c] = 1
                        if 0 <= nr < n and 0 <= nc < m:
                            dp[d][0][r][c] += dp[d][1][nr][nc]

                    if grid[r][c] == 0:
                        dp[d][1][r][c] = 1
                        if 0 <= nr < n and 0 <= nc < m:
                            dp[d][1][r][c] += dp[d][0][nr][nc]

        ans = 0

        for r in range(n):
            for c in range(m):
                if grid[r][c] != 1:
                    continue

                ans = max(ans, 1)

                for d, (dr, dc) in enumerate(dirs):
                    # No turn
                    nr, nc = r + dr, c + dc
                    if 0 <= nr < n and 0 <= nc < m:
                        ans = max(ans, 1 + dp[d][0][nr][nc])

                    # One clockwise turn after walking some steps in direction d
                    turn_d = cw[d]

                    cr, cc = r, c
                    step = 0

                    while True:
                        nr, nc = cr + dr, cc + dc
                        if not (0 <= nr < n and 0 <= nc < m):
                            break

                        expected = 2 if step % 2 == 0 else 0
                        if grid[nr][nc] != expected:
                            break

                        step += 1
                        cr, cc = nr, nc

                        tr, tc = cr + dirs[turn_d][0], cc + dirs[turn_d][1]
                        if 0 <= tr < n and 0 <= tc < m:
                            next_expect_parity = step % 2
                            ans = max(ans, 1 + step + dp[turn_d][next_expect_parity][tr][tc])
                        else:
                            ans = max(ans, 1 + step)

        return ans

