from typing import List
import heapq

class Solution:
    def maxSum(self, grid: List[List[int]], limits: List[int], k: int) -> int:
        if k == 0:
            return 0

        candidates = []
        for row, limit in zip(grid, limits):
            if limit == 0:
                continue
            row.sort(reverse=True)
            take = min(limit, len(row))
            candidates.extend(row[:take])

        if not candidates:
            return 0

        if k >= len(candidates):
            return sum(candidates)

        return sum(heapq.nlargest(k, candidates))

This works because for each row, the only elements worth considering are that row's top `limits[i]` values. After collecting all such eligible values, the answer is just the sum of the largest `k` among them, since selecting fewer than `k` is allowed and all values are non-negative.

class Solution:
    def maxSum(self, grid: list[list[int]], limits: list[int], k: int) -> int:
        # For each row, sort descending and take up to limits[i] largest elements
        candidates = []
        for i, row in enumerate(grid):
            sorted_row = sorted(row, reverse=True)
            candidates.extend(sorted_row[:limits[i]])

        # Sort all candidates descending and take top k
        candidates.sort(reverse=True)
        return sum(candidates[:k])

