class Solution:
    def maxDistance(self, side, points, k):
        def pos_on_perimeter(x, y):
            if y == 0:
                return x
            if x == side:
                return side + y
            if y == side:
                return 3 * side - x
            return 4 * side - y

        arr = sorted(pos_on_perimeter(x, y) for x, y in points)
        n = len(arr)
        L = 4 * side

        ext = arr + [x + L for x in arr]

        def manhattan_from_positions(a, b):
            d = b - a
            return min(d, L - d)

        def feasible(D):
            nxt = [n] * (2 * n)
            r = 0
            for i in range(2 * n):
                if r < i + 1:
                    r = i + 1
                while r < 2 * n and manhattan_from_positions(ext[i], ext[r]) < D:
                    r += 1
                nxt[i] = r

            max_pick = min(k, n)
            jump = [nxt[:]]
            p = 1
            while (1 << p) <= max_pick:
                prev = jump[-1]
                cur = [2 * n] * (2 * n + 1)
                for i in range(2 * n):
                    mid = prev[i]
                    cur[i] = prev[mid] if mid < 2 * n else 2 * n
                cur[2 * n] = 2 * n
                jump.append(cur)
                p += 1

            for s in range(n):
                cur = s
                need = k - 1
                bit = 0
                while need:
                    if need & 1:
                        cur = jump[bit][cur]
                        if cur >= s + n:
                            break
                    need >>= 1
                    bit += 1
                else:
                    if manhattan_from_positions(ext[cur], ext[s] + L) >= D:
                        return True
            return False

        lo, hi = 0, 2 * side
        while lo < hi:
            mid = (lo + hi + 1) // 2
            if feasible(mid):
                lo = mid
            else:
                hi = mid - 1
        return lo

