class Solution:
    def maxDistance(self, side, points, k):
        def pos_on_perimeter(x, y):
            if y == 0:
                return x
            if x == side:
                return side + y
            if y == side:
                return 3 * side - x
            return 4 * side - y

        arr = []
        for x, y in points:
            arr.append((pos_on_perimeter(x, y), x, y))
        arr.sort()

        n = len(arr)
        per = 4 * side
        pos = [p for p, _, _ in arr]
        xs = [x for _, x, _ in arr]
        ys = [y for _, _, y in arr]

        def manhattan(i, j):
            return abs(xs[i] - xs[j]) + abs(ys[i] - ys[j])

        def feasible(d):
            if k == 1:
                return True

            nxt = [[] for _ in range(n)]
            for i in range(n):
                for j in range(i + 1, n):
                    if pos[j] - pos[i] >= d and manhattan(i, j) >= d:
                        nxt[i].append(j)

            for start in range(n):
                dp = {start: 1}
                for _ in range(1, k):
                    ndp = {}
                    for last, cnt in dp.items():
                        if cnt < _:
                            continue
                        for nj in nxt[last]:
                            if nj <= start:
                                continue
                            if cnt + 1 > ndp.get(nj, 0):
                                ndp[nj] = cnt + 1
                    if not ndp:
                        break
                    dp = ndp

                for last, cnt in dp.items():
                    if cnt == k and manhattan(start, last) >= d and per - (pos[last] - pos[start]) >= d:
                        return True
            return False

        lo, hi = 0, 2 * side
        while lo < hi:
            mid = (lo + hi + 1) // 2
            if feasible(mid):
                lo = mid
            else:
                hi = mid - 1
        return lo

class Solution:
    def largestInteger(self, nums, k):
        n = len(nums)
        count = {}

        for i in range(n - k + 1):
            seen = set(nums[i:i + k])
            for x in seen:
                count[x] = count.get(x, 0) + 1

        ans = -1
        for x, c in count.items():
            if c == 1:
                ans = max(ans, x)

        return ans

