This works by:
- Enumerating every subarray of size k
- Counting, for each integer, in how many such subarrays it appears
- Returning the largest integer whose count is exactly 1

Time complexity: O((n - k + 1) * k)
Space complexity: O(distinct values)

class Solution:
    def longestPalindromicSubsequence(self, s: str, k: int) -> int:
        n = len(s)
        vals = [ord(c) - ord('a') for c in s]

        def cost(i: int, j: int) -> int:
            d = abs(vals[i] - vals[j])
            return min(d, 26 - d)

        dp = [[0] * (k + 1) for _ in range(n)]

        for i in range(n - 1, -1, -1):
            for ops in range(k + 1):
                dp[i][ops] = 1

            for j in range(i + 1, n):
                new = [0] * (k + 1)
                c = cost(i, j)

                for ops in range(k + 1):
                    best = dp[j][ops]
                    if new[ops] < best:
                        new[ops] = best

                    best = dp[j - 1][ops]
                    if new[ops] < best:
                        new[ops] = best

                    if c <= ops:
                        if j == i + 1:
                            best = 2
                        else:
                            best = 2 + prev[j - 1][ops - c]
                        if new[ops] < best:
                            new[ops] = best

                prev_col[j] = new
                dp[j] = new

            prev = [row[:] for row in dp]
            prev_col = dp

        memo = {}

        def solve(l: int, r: int, rem: int) -> int:
            if l > r:
                return 0
            if l == r:
                return 1
            key = (l, r, rem)
            if key in memo:
                return memo[key]

            ans = max(solve(l + 1, r, rem), solve(l, r - 1, rem))
            c = cost(l, r)
            if c <= rem:
                ans = max(ans, 2 + solve(l + 1, r - 1, rem - c))

            memo[key] = ans
            return ans

        return solve(0, n - 1, k)

