    def longestPalindromicSubsequence(self, s: str, k: int) -> int:
        n = len(s)

        def cost(a: str, b: str) -> int:
            d = abs(ord(a) - ord(b))
            return min(d, 26 - d)

        dp = [[[0] * (k + 1) for _ in range(n)] for _ in range(n)]

        for i in range(n):
            for ops in range(k + 1):
                dp[i][i][ops] = 1

        for length in range(2, n + 1):
            for i in range(n - length + 1):
                j = i + length - 1
                c = cost(s[i], s[j])
                for ops in range(k + 1):
                    best = dp[i + 1][j][ops] if i + 1 <= j else 0
                    if i <= j - 1:
                        best = max(best, dp[i][j - 1][ops])
                    if c <= ops:
                        if i + 1 <= j - 1:
                            best = max(best, 2 + dp[i + 1][j - 1][ops - c])
                        else:
                            best = max(best, 2)
                    dp[i][j][ops] = best

        return dp[0][n - 1][k]

