    def maxSum(self, nums, k, m):
        n = len(nums)
        pref = [0] * (n + 1)
        for i, x in enumerate(nums):
            pref[i + 1] = pref[i] + x

        NEG = -10**18

        # dp_prev[i] = max sum using exactly t-1 subarrays within nums[:i]
        dp_prev = [NEG] * (n + 1)
        dp_prev[0] = 0

        for t in range(1, k + 1):
            dp_cur = [NEG] * (n + 1)
            best = NEG

            for i in range(1, n + 1):
                dp_cur[i] = dp_cur[i - 1]

                if i >= m and dp_prev[i - m] != NEG:
                    cand = dp_prev[i - m] - pref[i - m]
                    if cand > best:
                        best = cand

                if best != NEG:
                    val = pref[i] + best
                    if val > dp_cur[i]:
                        dp_cur[i] = val

            dp_prev = dp_cur

        return dp_prev[n]

