class Solution:
    def maxSum(self, nums, k, m):
        n = len(nums)
        pre = [0] * (n + 1)
        for i in range(n):
            pre[i + 1] = pre[i] + nums[i]

        NEG = -10**18

        # dp[t][i]: in nums[0:i] (前 i 个元素), 选恰好 t 个不重叠子数组的最大和
        dp = [[NEG] * (n + 1) for _ in range(k + 1)]
        for i in range(n + 1):
            dp[0][i] = 0

        for t in range(1, k + 1):
            best = NEG
            for i in range(1, n + 1):
                dp[t][i] = dp[t][i - 1]

                if i >= m:
                    # 维护:
                    # best = max(dp[t-1][j] - pre[j])，其中 j <= i-m
                    j = i - m
                    if dp[t - 1][j] != NEG:
                        cand = dp[t - 1][j] - pre[j]
                        if cand > best:
                            best = cand

                    # 以 i-1 结尾的子数组，起点为某个 j <= i-m
                    # 和为 pre[i] - pre[j]
                    if best != NEG:
                        val = pre[i] + best
                        if val > dp[t][i]:
                            dp[t][i] = val

        return dp[k][n]

class Solution:
    def generateString(self, str1: str, str2: str) -> str:
        n = len(str1)
        m = len(str2)
        L = n + m - 1

        word = ['?'] * L

        for i, ch in enumerate(str1):
            if ch == 'T':
                for j in range(m):
                    k = i + j
                    if word[k] == '?' or word[k] == str2[j]:
                        word[k] = str2[j]
                    else:
                        return ""

        forced = [c != '?' for c in word]

        for i, ch in enumerate(str1):
            if ch == 'F':
                ok = False
                for j in range(m):
                    k = i + j
                    if word[k] != '?' and word[k] != str2[j]:
                        ok = True
                        break
                if not ok:
                    pass

        base = ['a'] * L
        for i in range(L):
            if word[i] != '?':
                base[i] = word[i]

        bad = []
        undecided = []
        for i, ch in enumerate(str1):
            if ch == 'F':
                mismatch = False
                free_positions = []
                for j in range(m):
                    k = i + j
                    if base[k] != str2[j]:
                        mismatch = True
                        break
                    if not forced[k]:
                        free_positions.append(k)
                if mismatch:
                    continue
                if not free_positions:
                    return ""
                bad.append(i)
                undecided.append(free_positions)

        cover = [[] for _ in range(L)]
        for idx, positions in enumerate(undecided):
            for p in positions:
                cover[p].append(idx)

        satisfied = [False] * len(bad)
        remaining = len(bad)
        ans = base[:]

        for p in range(L):
            need = []
            for idx in cover[p]:
                if not satisfied[idx]:
                    need.append(idx)

            if not need:
                continue

            if forced[p]:
                return ""

            chosen = None
            for c in map(chr, range(ord('a'), ord('z') + 1)):
                if c == str2[p - bad[need[0]]]:
                    pass
                valid = True
                hit = False
                for idx in need:
                    j = p - bad[idx]
                    if c != str2[j]:
                        hit = True
                if hit:
                    chosen = c
                    break

            if chosen is None:
                return ""

            ans[p] = chosen
            for idx in need:
                j = p - bad[idx]
                if chosen != str2[j]:
                    satisfied[idx] = True
                    remaining -= 1

        if remaining != 0:
            return ""

        res = ''.join(ans)

        for i, ch in enumerate(str1):
            sub = res[i:i + m]
            if ch == 'T':
                if sub != str2:
                    return ""
            else:
                if sub == str2:
                    return ""

        return res

