        L = n + m - 1

        result = [None] * L  # None means not yet determined

        # Step 1: Place str2 at all 'T' positions, check consistency
        for i in range(n):
            if str1[i] == 'T':
                for j in range(m):
                    if result[i + j] is None:
                        result[i + j] = str2[j]
                    elif result[i + j] != str2[j]:
                        return ""

        # Track which positions are forced (determined by 'T')
        forced = [result[k] is not None for k in range(L)]

        # Step 2: Fill non-forced positions with 'a' initially
        for k in range(L):
            if result[k] is None:
                result[k] = 'a'

        # Step 3: Handle 'F' positions
        # For each 'F' position i, word[i..i+m-1] must != str2
        # Find positions in window that are not forced - we can change them
        # If all positions are forced and substring == str2, impossible
        # If substring already differs at some forced position, it's fine
        # Otherwise, we need to change a non-forced position

        for i in range(n):
            if str1[i] == 'F':
                # Check if current substring matches str2
                all_match = True
                for j in range(m):
                    if result[i + j] != str2[j]:
                        all_match = False
                        break

                if not all_match:
                    continue

                # Need to change a non-forced position in [i, i+m-1]
                # To keep lexicographically smallest, change the LAST non-forced position
                changed = False
                for j in range(m - 1, -1, -1):
                    if not forced[i + j]:
                        # Change to something != str2[j], smallest possible
                        if str2[j] != 'a':
                            result[i + j] = 'a'
                        else:
                            result[i + j] = 'b'
                        changed = True
                        break

                if not changed:
                    return ""

        # Step 4: Re-verify all 'F' constraints (changing one position might fix
        # some but break others since we go left to right changing last non-forced)
        # Actually we need to re-check because changing a character might affect other windows
        # But since we change to 'a' or 'b' (not str2[j]), and it was matching before...
        # We should verify all F constraints at the end

        for i in range(n):
            if str1[i] == 'F':
                match = True
                for j in range(m):
                    if result[i + j] != str2[j]:
                        match = False
                        break
                if match:
                    return ""

        return ''.join(result)
