class Solution:
    def generateString(self, str1: str, str2: str) -> str:
        n = len(str1)
        m = len(str2)
        L = n + m - 1

        word = ['?'] * L

        for i, ch in enumerate(str1):
            if ch == 'T':
                for j in range(m):
                    pos = i + j
                    if word[pos] == '?' or word[pos] == str2[j]:
                        word[pos] = str2[j]
                    else:
                        return ""

        forced = [c != '?' for c in word]

        for i, ch in enumerate(str1):
            if ch == 'F':
                possible = True
                has_free_mismatch = False
                for j in range(m):
                    pos = i + j
                    if word[pos] == '?':
                        has_free_mismatch = True
                    elif word[pos] != str2[j]:
                        possible = False
                        break
                if possible and not has_free_mismatch:
                    return ""

        for i in range(L):
            if word[i] == '?':
                word[i] = 'a'

        def window_equal(start):
            for j in range(m):
                if word[start + j] != str2[j]:
                    return False
            return True

        bad_starts = []
        for i, ch in enumerate(str1):
            if ch == 'F' and window_equal(i):
                bad_starts.append(i)

        cover = [[] for _ in range(L)]
        for s in bad_starts:
            for p in range(s, s + m):
                if not forced[p]:
                    cover[p].append(s)

        broken = [False] * n

        for p in range(L):
            if forced[p]:
                continue

            if not cover[p]:
                continue

            original = word[p]
            changed = False

            for c_ord in range(ord('a'), ord('z') + 1):
                c = chr(c_ord)
                newly_broken = []
                for s in cover[p]:
                    if not broken[s] and c != str2[p - s]:
                        newly_broken.append(s)

                if newly_broken:
                    word[p] = c
                    for s in newly_broken:
                        broken[s] = True
                    changed = True
                    break

            if not changed:
                word[p] = original

        for i, ch in enumerate(str1):
            if ch == 'F' and window_equal(i):
                return ""

        return "".join(word)

class Solution:
    def generateString(self, str1: str, str2: str) -> str:
        n = len(str1)
        m = len(str2)
        L = n + m - 1

        word = ['?'] * L

        # 先处理所有 T 约束：对应区间必须等于 str2
        for i, ch in enumerate(str1):
            if ch == 'T':
                for j in range(m):
                    pos = i + j
                    c = str2[j]
                    if word[pos] == '?':
                        word[pos] = c
                    elif word[pos] != c:
                        return ""

        # 构造 KMP 自动机，用于按字符增量维护“当前后缀匹配了 str2 的前缀长度”
        pi = [0] * m
        for i in range(1, m):
            j = pi[i - 1]
            while j > 0 and str2[i] != str2[j]:
                j = pi[j - 1]
            if str2[i] == str2[j]:
                j += 1
            pi[i] = j

        trans = [[0] * 26 for _ in range(m + 1)]
        for state in range(m + 1):
            for c in range(26):
                ch = chr(ord('a') + c)
                if state < m and str2[state] == ch:
                    trans[state][c] = state + 1
                else:
                    j = state
                    if j == m:
                        j = pi[m - 1]
                    while j > 0 and str2[j] != ch:
                        j = pi[j - 1]
                    if str2[j] == ch:
                        j += 1
                    trans[state][c] = j

        # bad_end[i] = True 表示若在位置 i 结束了一个完整匹配，则对应起点 s=i-m+1 满足 str1[s]=='F'，因此不允许
        bad_end = [False] * L
        for s, ch in enumerate(str1):
            if ch == 'F':
                end = s + m - 1
                bad_end[end] = True

        # 后缀可行性 DP
        # dp[pos][state]: 从位置 pos 开始填，当前 KMP 状态为 state，是否可行
        dp = [[False] * (m + 1) for _ in range(L + 1)]
        for state in range(m + 1):
            dp[L][state] = (state != m)

        for pos in range(L - 1, -1, -1):
            forced = word[pos]
            chars = [forced] if forced != '?' else None
            for state in range(m + 1):
                ok = False
                if chars is not None:
                    cidx = ord(chars[0]) - ord('a')
                    ns = trans[state][cidx]
                    if not (ns == m and bad_end[pos]):
                        next_state = pi[m - 1] if ns == m else ns
                        if dp[pos + 1][next_state]:
                            ok = True
                else:
                    for cidx in range(26):
                        ns = trans[state][cidx]
                        if ns == m and bad_end[pos]:
                            continue
                        next_state = pi[m - 1] if ns == m else ns
                        if dp[pos + 1][next_state]:
                            ok = True
                            break
                dp[pos][state] = ok

        if not dp[0][0]:
            return ""

        # 贪心恢复字典序最小答案
        ans = []
        state = 0
        for pos in range(L):
            forced = word[pos]
            if forced != '?':
                cands = [forced]
            else:
                cands = [chr(ord('a') + i) for i in range(26)]

            chosen = None
            for ch in cands:
                cidx = ord(ch) - ord('a')
                ns = trans[state][cidx]
                if ns == m and bad_end[pos]:
                    continue
                next_state = pi[m - 1] if ns == m else ns
                if dp[pos + 1][next_state]:
                    chosen = ch
                    state = next_state
                    break

            if chosen is None:
                return ""
            ans.append(chosen)

        return "".join(ans)

Looking at this problem, I need to find the lexicographically smallest string `word` of length `n + m - 1` such that:
- At every position `i` where `str1[i] == 'T'`, the substring `word[i..i+m-1]` equals `str2`
- At every position `i` where `str1[i] == 'F'`, the substring `word[i..i+m-1]` does NOT equal `str2`

**Approach:**

1. **Handle 'T' positions first:** For all positions where `str1[i] == 'T'`, the characters in `word[i..i+m-1]` are forced to be `str2`. Check consistency (overlapping T positions must agree on character values using KMP/failure function logic).

2. **Handle 'F' positions:** For positions where `str1[i] == 'F'`, the substring must differ from `str2` in at least one position. For free (unconstrained) positions, we try 'a' first (lexicographically smallest). If all characters happen to match `str2`, we need to change at least one free position in that window.

3. **Use KMP failure function** to check if two 'T' positions at distance `d` apart are compatible (the overlap of `str2` with itself at offset `d` must be consistent).

4. For unconstrained positions, default to 'a'. Then verify all 'F' constraints. If an 'F' window has all positions fixed and equals `str2`, it's impossible. If an 'F' window has some free positions but currently matches `str2`, change the last free position to 'b' (to keep lexicographic order small). If that's still not enough, backtrack.

class Solution:
    def generateString(self, str1: str, str2: str) -> str:
        n = len(str1)
        m = len(str2)
        L = n + m - 1

        # Compute KMP failure function for str2
        fail = [0] * m
        k = 0
        for i in range(1, m):
            while k > 0 and str2[k] != str2[i]:
                k = fail[k - 1]
            if str2[k] == str2[i]:
                k += 1
            fail[i] = k

        # Check consistency of T positions
        # fixed[j] = character forced at position j, None if free
        fixed = [None] * L

        t_positions = [i for i in range(n) if str1[i] == 'T']

        # Check overlapping T positions are compatible
        for i in t_positions:
            for j in range(m):
                if fixed[i + j] is not None:
                    if fixed[i + j] != str2[j]:
                        return ""
                else:
                    fixed[i + j] = str2[j]

        # Build the word: free positions get 'a' initially
        word = list(fixed)
        is_free = [False] * L
        for j in range(L):
            if word[j] is None:
                word[j] = 'a'
                is_free[j] = True

        # Check F constraints
        f_positions = [i for i in range(n) if str1[i] == 'F']

        # For each F position, check if word[i..i+m-1] == str2
        # If so, we need to change a free position in that window
        # Collect F positions that need fixing
        for i in f_positions:
            # Check if current substring matches str2
            match = all(word[i + j] == str2[j] for j in range(m))
            if not match:
                continue

            # Need to change at least one free position in [i, i+m-1]
            # Find the last free position in this window (to keep lex order small)
            changed = False
            for j in range(m - 1, -1, -1):
                if is_free[i + j]:
                    # Change to 'b' (smallest change from 'a' that differs)
                    word[i + j] = 'b'
                    is_free[i + j] = False  # now committed
                    changed = True
                    break
            if not changed:
                return ""

        # Re-verify all F constraints after changes
        for i in f_positions:
            match = all(word[i + j] == str2[j] for j in range(m))
            if match:
                # Try to find any free position to change
                found = False
                for j in range(m - 1, -1, -1):
                    if is_free[i + j]:
                        word[i + j] = 'b'
                        is_free[i + j] = False
                        found = True
                        break
                if not found:
                    return ""

        # Final verification
        for i in f_positions:
            if all(word[i + j] == str2[j] for j in range(m)):
                return ""

        return "".join(word)

