class Solution:
    def findMaxSum(self, nums1: List[int], nums2: List[int], k: int) -> List[int]:
        n = len(nums1)
        ans = [0] * n

        pairs = sorted((nums1[i], nums2[i], i) for i in range(n))

        heap = []
        topk_sum = 0
        i = 0

        while i < n:
            j = i
            while j < n and pairs[j][0] == pairs[i][0]:
                j += 1

            for t in range(i, j):
                _, _, idx = pairs[t]
                ans[idx] = topk_sum

            for t in range(i, j):
                _, val2, _ = pairs[t]
                if len(heap) < k:
                    heapq.heappush(heap, val2)
                    topk_sum += val2
                elif val2 > heap[0]:
                    topk_sum += val2 - heapq.heapreplace(heap, val2)

            i = j

        return ans

