    def numOfUnplacedFruits(self, fruits, baskets):
        n = len(baskets)
        size = 1
        while size < n:
            size <<= 1

        seg = [0] * (2 * size)
        for i in range(n):
            seg[size + i] = baskets[i]
        for i in range(size - 1, 0, -1):
            seg[i] = max(seg[i << 1], seg[i << 1 | 1])

        def use_leftmost(x):
            if seg[1] < x:
                return False
            idx = 1
            left = 0
            right = size - 1
            while idx < size:
                if seg[idx << 1] >= x:
                    idx <<= 1
                    right = (left + right) >> 1
                else:
                    idx = idx << 1 | 1
                    left = ((left + right) >> 1) + 1
            seg[idx] = 0
            idx >>= 1
            while idx:
                seg[idx] = max(seg[idx << 1], seg[idx << 1 | 1])
                idx >>= 1
            return True

        unplaced = 0
        for f in fruits:
