                    left = (left + right) // 2 + 1
            pos = idx - size
            return pos if pos < n else -1

        unplaced = 0
        for f in fruits:
            pos = find_leftmost(f)
            if pos == -1:
                unplaced += 1
            else:
                update(pos, 0)

