        by_right = [[] for _ in range(n + 1)]
        for a, b in conflictingPairs:
            if a > b:
                a, b = b, a
            by_right[b].append(a)

        best1 = [0] * (n + 1)
        best2 = [0] * (n + 1)
        cnt1 = [0] * (n + 1)

