    def minZeroArray(self, nums, queries):
        n = len(nums)
        m = len(queries)

        if all(x == 0 for x in nums):
            return 0

        def can_make_zero(k):
            dp = [1] + [0] * 1000

            for i in range(n):
                possible = dp[:]
                for j in range(k):
                    l, r, val = queries[j]
                    if l <= i <= r:
                        new_possible = possible[:]
                        for s in range(val, nums[i] + 1):
                            if possible[s - val]:
                                new_possible[s] = 1
                        possible = new_possible
                if not possible[nums[i]]:
                    return False
            return True

