    def minZeroArray(self, nums, queries):
        n = len(nums)
        m = len(queries)

        def can_make_zero(k):
            for i in range(n):
                reachable = [False] * (nums[i] + 1)
                reachable[0] = True

                for j in range(k):
                    l, r, val = queries[j]
                    if l <= i <= r:
                        for s in range(nums[i] - val, -1, -1):
                            if reachable[s]:
                                reachable[s + val] = True

                if not reachable[nums[i]]:
                    return False
            return True

        if all(x == 0 for x in nums):
            return 0

        if not can_make_zero(m):
            return -1

        left, right = 0, m
