    def beautifulNumbers(self, l: int, r: int) -> int:
        from functools import lru_cache

        def count_up_to(n: int) -> int:
            if n <= 0:
                return 0

            digits = list(map(int, str(n)))
            m = len(digits)
            max_sum = 9 * m

            @lru_cache(None)
            def dp(pos: int, tight: bool, started: bool, digit_sum: int, prod_mod: int, target_sum: int) -> int:
                if pos == m:
                    return 1 if started and digit_sum == target_sum and prod_mod == 0 else 0

                limit = digits[pos] if tight else 9
                ans = 0

                for d in range(limit + 1):
                    ntight = tight and (d == limit)

                    if not started and d == 0:
                        ans += dp(pos + 1, ntight, False, 0, 1 % target_sum, target_sum)
                    else:
                        if not started:
                            nsum = d
                            nprod_mod = d % target_sum
                        else:
                            nsum = digit_sum + d
                            if nsum > target_sum:
                                continue
                            nprod_mod = (prod_mod * d) % target_sum
                        ans += dp(pos + 1, ntight, True, nsum, nprod_mod, target_sum)

                return ans

            total = 0
            for s in range(1, max_sum + 1):
                total += dp(0, True, False, 0, 1 % s, s)
            return total

        return count_up_to(r) - count_up_to(l - 1)

