    def numberOfComponents(self, properties, k):
        n = len(properties)
        sets = [set(row) for row in properties]

        parent = list(range(n))
        rank = [0] * n

        def find(x):
            while parent[x] != x:
                parent[x] = parent[parent[x]]
                x = parent[x]
            return x

        def union(a, b):
            ra, rb = find(a), find(b)
            if ra == rb:
                return
            if rank[ra] < rank[rb]:
                parent[ra] = rb
            elif rank[ra] > rank[rb]:
                parent[rb] = ra
            else:
                parent[rb] = ra
                rank[ra] += 1

        for i in range(n):
            for j in range(i + 1, n):
                if len(sets[i] & sets[j]) >= k:
                    union(i, j)

        return sum(1 for i in range(n) if find(i) == i)

This uses:
- set(row) so duplicates only count once, matching “distinct integers”
- pairwise comparison of all arrays
- union-find to count connected components

Time complexity:
- O(n^2 * m) in practice here, which is fine for n, m <= 100.

