class Solution:
    def minTime(self, skill, mana):
        n = len(skill)
        m = len(mana)

        pref = [0] * n
        pref[0] = skill[0]
        for i in range(1, n):
            pref[i] = pref[i - 1] + skill[i]

        start = 0
        prev_mana = mana[0]

        for j in range(1, m):
            cur_mana = mana[j]
            need = 0
            for i in range(n):
                val = prev_mana * pref[i] - cur_mana * (pref[i - 1] if i > 0 else 0)
                if val > need:
                    need = val
            start += need
            prev_mana = cur_mana

        return start + mana[-1] * pref[-1]

