    def minTime(self, skill, mana):
        n = len(skill)
        m = len(mana)

        prefix = [0] * n
        prefix[0] = skill[0]
        for i in range(1, n):
            prefix[i] = prefix[i - 1] + skill[i]

        start = 0
        prev_finish = [0] * n

        for j in range(m):
            x = mana[j]

            if j == 0:
                for i in range(n):
                    prev_finish[i] = x * prefix[i]
                start = 0
                continue

            need = prev_finish[0]
            for i in range(1, n):
                candidate = prev_finish[i] - x * prefix[i - 1]
                if candidate > need:
                    need = candidate

            start = need

            for i in range(n):
                prev_finish[i] = start + x * prefix[i]

        return prev_finish[-1]

