class Solution:
    def minOperations(self, queries):
        def prefix(n):
            if n <= 0:
                return 0
            total = 0
            k = 1
            p = 1
            while p <= n:
                nxt = p * 4
                right = min(n, nxt - 1)
                total += k * (right - p + 1)
                p = nxt
                k += 1
            return total

        ans = 0
        for l, r in queries:
            s = prefix(r) - prefix(l - 1)
            ans += (s + 1) // 2
        return ans

