    def minOperations(self, queries):
        def prefix_steps(n):
            if n <= 0:
                return 0

            total = 0
            k = 1
            start = 1

            while start <= n:
                end = min(n, (1 << (2 * k)) - 1)
                total += (end - start + 1) * k
                start = 1 << (2 * k)
                k += 1

            return total

        ans = 0
        for l, r in queries:
            total_steps = prefix_steps(r) - prefix_steps(l - 1)
            ans += (total_steps + 1) // 2

        return ans

