    def longestPalindrome(self, s: str, t: str) -> int:
        def longest_inside(x: str) -> int:
            n = len(x)
            best = 1
            for c in range(n):
                l = r = c
                while l >= 0 and r < n and x[l] == x[r]:
                    best = max(best, r - l + 1)
                    l -= 1
                    r += 1
                l, r = c, c + 1
                while l >= 0 and r < n and x[l] == x[r]:
                    best = max(best, r - l + 1)
                    l -= 1
                    r += 1
            return best

