        best_suf = [[0] * n for _ in range(n)]
        for i in range(n):
            best_suf[i][i] = 1
        for i in range(n - 2, -1, -1):
            for j in range(i + 1, n):
                if s[i] == s[j]:
                    best_suf[i][j] = 2 + (best_suf[i + 1][j - 1] if i + 1 <= j - 1 else 0)
                else:
                    best_suf[i][j] = max(best_suf[i + 1][j], best_suf[i][j - 1])

        best_pre = [[0] * m for _ in range(m)]
        for i in range(m):
            best_pre[i][i] = 1
        for i in range(m - 2, -1, -1):
            for j in range(i + 1, m):
                if t[i] == t[j]:
                    best_pre[i][j] = 2 + (best_pre[i + 1][j - 1] if i + 1 <= j - 1 else 0)
                else:
                    best_pre[i][j] = max(best_pre[i + 1][j], best_pre[i][j - 1])

        ans = max(longest_inside(s), longest_inside(t))

        dp = [[0] * m for _ in range(n)]
        for i in range(n):
            for j in range(m):
                if s[i] == t[j]:
                    dp[i][j] = 1 + (dp[i - 1][j + 1] if i > 0 and j + 1 < m else 0)
                    k = dp[i][j]
                    ans = max(ans, 2 * k)
                    if i + 1 < n:
                        ans = max(ans, 2 * k + best_suf[i + 1][n - 1])
                    if j > 0:
                        ans = max(ans, 2 * k + best_pre[0][j - 1])

