    def longestPalindrome(self, s: str, t: str) -> int:
        def longest_pal_substring(u: str) -> int:
            n = len(u)
            best = 1
            for center in range(n):
                l = r = center
                while l >= 0 and r < n and u[l] == u[r]:
                    best = max(best, r - l + 1)
                    l -= 1
                    r += 1
                l, r = center, center + 1
                while l >= 0 and r < n and u[l] == u[r]:
                    best = max(best, r - l + 1)
                    l -= 1
                    r += 1
            return best

        n, m = len(s), len(t)
        ans = max(longest_pal_substring(s), longest_pal_substring(t))

        # dp[i][j] = longest common prefix length of s[i:] and reversed(t)[j:]
        rt = t[::-1]
        dp = [[0] * (m + 1) for _ in range(n + 1)]
        for i in range(n - 1, -1, -1):
            for j in range(m - 1, -1, -1):
                if s[i] == rt[j]:
                    dp[i][j] = dp[i + 1][j + 1] + 1

        # bestS[i] = longest palindromic substring of s that starts at i
        bestS = [0] * n
        for i in range(n):
            for j in range(i, n):
                sub = s[i:j + 1]
                if sub == sub[::-1]:
                    bestS[i] = max(bestS[i], j - i + 1)

        # bestTEnd[j] = longest palindromic substring of t that ends at j
        bestTEnd = [0] * m
        for i in range(m):
            for j in range(i, m):
                sub = t[i:j + 1]
                if sub == sub[::-1]:
                    bestTEnd[j] = max(bestTEnd[j], j - i + 1)

        # Build palindrome using both strings.
        # Match k chars from end of substring in s with start of substring in t.
        # Then optionally place a palindromic middle entirely inside s or t.
        for i in range(n):
            for j in range(m):
                k = dp[i][m - 1 - j]
                for x in range(1, k + 1):
                    ans = max(ans, 2 * x)
                    if i + x < n:
                        ans = max(ans, 2 * x + bestS[i + x])
                    if j - x >= 0:
                        ans = max(ans, 2 * x + bestTEnd[j - x])

        return ans

