    def longestPalindrome(self, s: str, t: str) -> int:
        def longest_pal_substring(u: str) -> int:
            n = len(u)
            best = 1
            for c in range(n):
                l = r = c
                while l >= 0 and r < n and u[l] == u[r]:
                    best = max(best, r - l + 1)
                    l -= 1
                    r += 1
                l, r = c, c + 1
                while l >= 0 and r < n and u[l] == u[r]:
                    best = max(best, r - l + 1)
                    l -= 1
                    r += 1
            return best

        n, m = len(s), len(t)

        ans = max(longest_pal_substring(s), longest_pal_substring(t))

        # dp[i][j]: longest common substring length of s[i:] and reversed(t)[j:]
        rt = t[::-1]
        dp = [[0] * (m + 1) for _ in range(n + 1)]
        for i in range(n - 1, -1, -1):
            for j in range(m - 1, -1, -1):
                if s[i] == rt[j]:
                    dp[i][j] = dp[i + 1][j + 1] + 1

        # Use a matched block across s and t as the two mirrored sides.
        # Then optionally extend by one-side palindrome continuation from either s or t.
        for i in range(n):
            for j in range(m):
                k = dp[i][m - 1 - j]
                for l in range(1, k + 1):
                    ans = max(ans, 2 * l)

                    # Add a palindromic middle part from s after the left matched block
                    rem_s_start = i + l
                    if rem_s_start < n:
                        for end in range(rem_s_start, n):
                            sub = s[rem_s_start:end + 1]
                            if sub == sub[::-1]:
                                ans = max(ans, 2 * l + len(sub))

                    # Add a palindromic middle part from t before the right matched block
                    rem_t_end = j - l
                    if rem_t_end >= 0:
                        for start in range(rem_t_end + 1):
                            sub = t[start:rem_t_end + 1]
                            if sub == sub[::-1]:
                                ans = max(ans, 2 * l + len(sub))

        return ans

class Solution:
    def minimumPairRemoval(self, nums):
        def is_non_decreasing(arr):
            for i in range(1, len(arr)):
                if arr[i] < arr[i - 1]:
                    return False
            return True

        ops = 0
        arr = nums[:]

        while not is_non_decreasing(arr):
            min_sum = arr[0] + arr[1]
            idx = 0

            for i in range(1, len(arr) - 1):
                s = arr[i] + arr[i + 1]
                if s < min_sum:
                    min_sum = s
                    idx = i

            arr = arr[:idx] + [arr[idx] + arr[idx + 1]] + arr[idx + 2:]
            ops += 1

        return ops

