class Solution:
    def minimumPairRemoval(self, nums: list[int]) -> int:
        ops = 0
        while True:
            # Check if non-decreasing
            is_sorted = all(nums[i] <= nums[i + 1] for i in range(len(nums) - 1))
            if is_sorted:
                return ops

            # Find adjacent pair with minimum sum (leftmost if tie)
            min_sum = float('inf')
            min_idx = 0
            for i in range(len(nums) - 1):
                s = nums[i] + nums[i + 1]
                if s < min_sum:
                    min_sum = s
                    min_idx = i

            # Replace the pair with their sum
            nums[min_idx] = min_sum
            nums.pop(min_idx + 1)
            ops += 1

