    def maxProduct(self, nums, k, limit):
        # dp_even[s] = maximum product <= limit for a non-empty subsequence
        # whose alternating sum is s and whose length is even
        # dp_odd[s] = same, but odd length
        #
        # Transition when appending x:
        # even -> odd : new_sum = s + x
        # odd  -> even: new_sum = s - x
        #
        # Also start a new subsequence [x]: odd length, sum = x, product = x

        dp_even = {}
        dp_odd = {}

        for x in nums:
            new_even = dp_even.copy()
            new_odd = dp_odd.copy()

            # Start new subsequence [x]
            if x <= limit:
                prev = new_odd.get(x, -1)
                if x > prev:
                    new_odd[x] = x

            # Append x to even-length subsequences -> odd-length
