class Solution:
    def maxProduct(self, nums, k, limit):
        # dp_even[s]: set of achievable products (<= limit) for subsequences
        # whose current length is even and alternating sum is s
        # dp_odd[s]: same, but current length is odd
        #
        # When appending x:
        # even -> odd, new sum = s + x
        # odd  -> even, new sum = s - x
        #
        # Also, starting a new subsequence with [x]:
        # odd sum = x, product = x

        dp_even = {}
        dp_odd = {}

        for x in nums:
            new_even = {s: set(ps) for s, ps in dp_even.items()}
            new_odd = {s: set(ps) for s, ps in dp_odd.items()}

            # Start new subsequence [x]
            if x <= limit:
                if x not in new_odd:
                    new_odd[x] = set()
                new_odd[x].add(x)

            # Extend even-length subsequences
            for s, products in dp_even.items():
                ns = s + x
                target = new_odd.setdefault(ns, set())
                for p in products:
                    np = p * x
                    if np <= limit:
                        target.add(np)

            # Extend odd-length subsequences
            for s, products in dp_odd.items():
                ns = s - x
                target = new_even.setdefault(ns, set())
                for p in products:
                    np = p * x
                    if np <= limit:
                        target.add(np)

            dp_even = new_even
            dp_odd = new_odd

        ans = -1
        if k in dp_even and dp_even[k]:
            ans = max(ans, max(dp_even[k]))
        if k in dp_odd and dp_odd[k]:
            ans = max(ans, max(dp_odd[k]))
        return ans

