    def distanceSum(self, m: int, n: int, k: int) -> int:
        MOD = 10**9 + 7
        total_cells = m * n

        if k < 2:
            return 0

        def mod_pow(a, b):
            res = 1
            a %= MOD
            while b:
                if b & 1:
                    res = res * a % MOD
                a = a * a % MOD
                b >>= 1
            return res

        maxv = total_cells
        fact = [1] * (maxv + 1)
        for i in range(1, maxv + 1):
            fact[i] = fact[i - 1] * i % MOD

        invfact = [1] * (maxv + 1)
        invfact[maxv] = mod_pow(fact[maxv], MOD - 2)
        for i in range(maxv, 0, -1):
            invfact[i - 1] = invfact[i] * i % MOD

        def comb(a, b):
            if b < 0 or b > a:
                return 0
            return fact[a] * invfact[b] % MOD * invfact[a - b] % MOD

        ways = comb(total_cells - 2, k - 2)

        row_sum = 0
        for d in range(1, m):
            row_sum = (row_sum + d * (m - d)) % MOD
        row_contrib = row_sum * n % MOD * n % MOD

        col_sum = 0
        for d in range(1, n):
            col_sum = (col_sum + d * (n - d)) % MOD
        col_contrib = col_sum * m % MOD * m % MOD

        total_pair_distance = (row_contrib + col_contrib) % MOD
        return total_pair_distance * ways % MOD

