class Solution:
    def minCostGoodCaption(self, caption: str) -> str:
        n = len(caption)
        if n < 3:
            return ""

        vals = [ord(c) - 97 for c in caption]

        pref = [[0] * (n + 1) for _ in range(26)]
        for ch in range(26):
            pc = pref[ch]
            for i, v in enumerate(vals):
                pc[i + 1] = pc[i] + abs(v - ch)

        INF = 10**18
        dp = [INF] * (n + 1)
        pick = [None] * (n + 1)
        dp[n] = 0

        def seg_cost(ch, l, r):
            return pref[ch][r] - pref[ch][l]

        for i in range(n - 1, -1, -1):
            best_cost = INF
            best_choice = None

            for ch in range(26):
                if i + 3 <= n:
                    c = seg_cost(ch, i, i + 3) + dp[i + 3]
                    cand = (ch, 3)
                    if c < best_cost or (c == best_cost and cand < best_choice):
                        best_cost = c
                        best_choice = cand

                j = i + 4
                while j <= n:
                    c = seg_cost(ch, i, j) + dp[j]
                    cand = (ch, j - i)
                    if c < best_cost or (c == best_cost and cand < best_choice):
                        best_cost = c
                        best_choice = cand
                    j += 1

            dp[i] = best_cost
            pick[i] = best_choice

        if dp[0] >= INF:
            return ""

        res = []
        i = 0
        while i < n:
            ch, length = pick[i]
            res.append(chr(97 + ch) * length)
            i += length

        return "".join(res)

class Solution:
    def minCostGoodCaption(self, caption: str) -> str:
        n = len(caption)
        if n < 3:
            return ""

        vals = [ord(c) - 97 for c in caption]
        INF = 10**18

        # dp[i]: minimum cost to convert caption[i:] into a good caption
        dp = [INF] * (n + 1)
        dp[n] = 0

        # choice info for reconstruction:
        # choice[i] = (block_len, char_val)
        choice = [None] * (n + 1)

        # suffix cost to make caption[i:j+1] all equal to c
        # We compute block costs on the fly using prefix sums per character.
        pref = [[0] * (n + 1) for _ in range(26)]
        for c in range(26):
            for i, v in enumerate(vals):
                pref[c][i + 1] = pref[c][i] + abs(v - c)

        def block_cost(l, r, c):
            return pref[c][r] - pref[c][l]

        # To compare lexicographically among equal-cost solutions:
        # compare candidate:
        #   s1 = chr(c1) * len1 + best suffix from i+len1
        #   s2 = chr(c2) * len2 + best suffix from i+len2
        # return True if candidate1 is lexicographically smaller
        from functools import lru_cache

        @lru_cache(None)
        def build(i):
            if i == n:
                return ""
            ln, ch = choice[i]
            return chr(ch + 97) * ln + build(i + ln)

        def lex_smaller(len1, c1, next1, len2, c2, next2):
            m = min(len1, len2)
            if c1 != c2:
                return c1 < c2
            if len1 != len2:
                # first m chars equal
                if len1 < len2:
                    # s1 ends block first, next char from suffix1 vs c2
                    sfx1 = build(next1)
                    if not sfx1:
                        return True
                    return ord(sfx1[0]) - 97 < c2
                else:
                    sfx2 = build(next2)
                    if not sfx2:
                        return False
                    return c1 < ord(sfx2[0]) - 97
            return build(next1) < build(next2)

        for i in range(n - 1, -1, -1):
            best_cost = INF
            best_choice = None

            # block length can be any >= 3
            for j in range(i + 3, n + 1):
                if dp[j] == INF:
                    continue
                length = j - i
                for c in range(26):
                    cost = block_cost(i, j, c) + dp[j]
                    if cost < best_cost:
                        best_cost = cost
                        best_choice = (length, c)
                    elif cost == best_cost:
                        if best_choice is None:
                            best_choice = (length, c)
                        else:
                            blen, bc = best_choice
                            if lex_smaller(length, c, j, blen, bc, i + blen):
                                best_choice = (length, c)

            dp[i] = best_cost
            choice[i] = best_choice

        if dp[0] == INF:
            return ""
        return build(0)

