    def separateSquares(self, squares):
        total_area = 0.0
        low = float('inf')
        high = 0.0

        for _, y, l in squares:
            total_area += l * l
            low = min(low, y)
            high = max(high, y + l)

        target = total_area / 2.0

        def area_below(line_y):
            area = 0.0
            for _, y, l in squares:
                if line_y <= y:
                    continue
                if line_y >= y + l:
                    area += l * l
                else:
                    area += l * (line_y - y)
            return area

        for _ in range(70):
            mid = (low + high) / 2.0
            if area_below(mid) >= target:
                high = mid
            else:
                low = mid

        return high

