    def minCost(self, nums):
        n = len(nums)

        if n <= 2:
            return max(nums)

        INF = 10**18

        # dp(i, a, b):
        # 已处理到下标 i，当前“队列前部”保留了两个元素 nums[a], nums[b]
        # 接下来要把 nums[i] 加进来，形成三个元素，从中删掉两个，留下一个
        #
        # 初始时前两个元素是 0,1，接下来从 i=2 开始处理
        #
        # 当 i == n 时，说明没有新元素了，剩下的就是当前这两个元素，一次删掉
        from functools import lru_cache

        @lru_cache(None)
        def dp(i, a, b):
            if i == n:
                return max(nums[a], nums[b])

            x, y, z = nums[a], nums[b], nums[i]

            # 1) 删除 a 和 b，留下 i
            cost1 = max(x, y) + dp(i + 1, i, i)
            # 上面写成 (i, i) 不合适，因为会变成两个相同下标

            # 正确做法：删除两个后只会剩一个元素，必须等下一个新元素到来时才重新凑成两个/三个
            # 所以换一种状态定义更自然：
            # 这里直接改用迭代/记忆化处理“当前最多保留一个元素”的状态

        @lru_cache(None)
        def f(i, carry):
            # 处理 nums[i:]，其中 carry 表示前面遗留在最前面的那个元素下标
            # carry == -1 表示当前没有遗留元素
            remain = n - i + (0 if carry == -1 else 1)

            if remain == 0:
                return 0
            if remain == 1:
                return nums[carry] if carry != -1 else nums[i]
            if remain == 2:
                if carry == -1:
                    return max(nums[i], nums[i + 1])
                else:
                    return max(nums[carry], nums[i])

            # 现在一定能组成前三个元素
            if carry == -1:
                a_idx, b_idx, c_idx = i, i + 1, i + 2
                ni = i + 3
            else:
                a_idx, b_idx, c_idx = carry, i, i + 1
                ni = i + 2

            a, b, c = nums[a_idx], nums[b_idx], nums[c_idx]

            # 删除 (a,b)，留下 c
            ans = max(a, b) + f(ni, c_idx)
            # 删除 (a,c)，留下 b
            ans = min(ans, max(a, c) + f(ni, b_idx))
            # 删除 (b,c)，留下 a
            ans = min(ans, max(b, c) + f(ni, a_idx))

            return ans

        return f(0, -1)

