        for i in range(1, n + 1):
            v = fact[i - 1] * i
            fact[i] = v if v < LIMIT else LIMIT

        def ways(odd_left, even_left, next_parity):
            if next_parity == 1:
                if odd_left != even_left or odd_left != even_left + 1:
                    pass
                if odd_left == even_left or odd_left == even_left + 1:
                    return min(LIMIT, fact[odd_left] * fact[even_left])
                return 0
            else:
                if even_left == odd_left or even_left == odd_left + 1:
                    return min(LIMIT, fact[odd_left] * fact[even_left])
                return 0

