                    ans.append(x)
                    if p == 1:
                        odd_nums.pop(idx)
                    else:
                        even_nums.pop(idx)
                    prev_parity = p
                    break

        return ans

class Solution:
    def permute(self, n: int, k: int):
        odds = [x for x in range(1, n + 1) if x % 2 == 1]
        evens = [x for x in range(1, n + 1) if x % 2 == 0]

        odd_cnt = len(odds)
        even_cnt = len(evens)
        LIMIT = 10**18

        fact = [1] * (n + 1)
        for i in range(1, n + 1):
            fact[i] = min(LIMIT, fact[i - 1] * i)

        def ways(o, e, need_parity):
            if need_parity == 1:
                if o != e and o != e + 1:
                    return 0
                return fact[o] * fact[e] if fact[o] * fact[e] < LIMIT else LIMIT
            else:
                if e != o and e != o + 1:
                    return 0
                return fact[o] * fact[e] if fact[o] * fact[e] < LIMIT else LIMIT

        total = 0
        if odd_cnt == even_cnt:
            total = min(LIMIT, ways(odd_cnt, even_cnt, 1) + ways(odd_cnt, even_cnt, 0))
        elif odd_cnt == even_cnt + 1:
            total = ways(odd_cnt, even_cnt, 1)
        elif even_cnt == odd_cnt + 1:
            total = ways(odd_cnt, even_cnt, 0)
        else:
            total = 0

        if k > total:
            return []

        ans = []
        need = -1  # -1 means any parity for first position

        for _ in range(n):
            chosen = False
            for x in range(1, n + 1):
                if x in ans:
                    continue
                p = x % 2
                if need != -1 and p != need:
                    continue

                rem_o = odd_cnt - (1 if p == 1 else 0)
                rem_e = even_cnt - (1 if p == 0 else 0)
                next_need = 1 - p
                cnt = ways(rem_o, rem_e, next_need)

                if k > cnt:
                    k -= cnt
                else:
                    ans.append(x)
                    if p == 1:
                        odd_cnt -= 1
                    else:
                        even_cnt -= 1
                    need = next_need
                    chosen = True
                    break

            if not chosen:
                return []

        return ans

