class TrieNode:
    __slots__ = ("children", "cnt", "depth")
    def __init__(self, depth=0):
        self.children = {}
        self.cnt = 0
        self.depth = depth


class SegmentTree:
    def __init__(self, arr):
        self.n = len(arr)
        size = 1
        while size < self.n:
            size <<= 1
        self.size = size
        self.seg = [0] * (2 * size)
        for i, v in enumerate(arr):
            self.seg[size + i] = v
        for i in range(size - 1, 0, -1):
            self.seg[i] = max(self.seg[i << 1], self.seg[i << 1 | 1])

    def update(self, idx, val):
        i = self.size + idx
        self.seg[i] = val
        i >>= 1
        while i:
            nv = self.seg[i << 1]
            rv = self.seg[i << 1 | 1]
            self.seg[i] = nv if nv >= rv else rv
            i >>= 1

    def query_max(self):
        return self.seg[1]


class Solution:
    def longestCommonPrefix(self, words, k):
        n = len(words)
        if n - 1 < k:
            return [0] * n

        root = TrieNode(0)
        paths = []

        for w in words:
            node = root
            cur_path = []
            for ch in w:
                nxt = node.children.get(ch)
                if nxt is None:
                    nxt = TrieNode(node.depth + 1)
                    node.children[ch] = nxt
                node = nxt
                node.cnt += 1
                cur_path.append(node)
            paths.append(cur_path)

        max_depth = 0
        freq = {}
        stack = [root]
        while stack:
            node = stack.pop()
            for child in node.children.values():
                d = child.depth
                if child.cnt >= k:
                    freq[d] = freq.get(d, 0) + 1
                    if d > max_depth:
                        max_depth = d
                stack.append(child)

        if max_depth == 0:
            return [0] * n

        base = [0] * max_depth
        for d, c in freq.items():
            if c > 0:
                base[d - 1] = d

        seg = SegmentTree(base)
        ans = [0] * n

        for i, path in enumerate(paths):
            changed = []
            for node in path:
                if node.cnt == k:
                    idx = node.depth - 1
                    freq[node.depth] -= 1
                    if freq[node.depth] == 0:
                        seg.update(idx, 0)
                        changed.append((idx, node.depth, True))
                    else:
                        changed.append((idx, node.depth, False))

            ans[i] = seg.query_max()

            for idx, depth, zeroed in changed:
                freq[depth] += 1
                if zeroed:
                    seg.update(idx, depth)

        return ans

class Solution:
    def longestCommonPrefix(self, words, k):
        n = len(words)
        if n - 1 < k:
            return [0] * n

        trie = [{'next': {}, 'cnt': 0, 'depth': 0}]
        word_path_nodes = []

        for w in words:
            cur = 0
            path = []
            for ch in w:
                nxt = trie[cur]['next']
                if ch not in nxt:
                    nxt[ch] = len(trie)
                    trie.append({'next': {}, 'cnt': 0, 'depth': trie[cur]['depth'] + 1})
                cur = nxt[ch]
                trie[cur]['cnt'] += 1
                path.append(cur)
            word_path_nodes.append(path)

        max_depth = 0
        for node in trie:
            if node['depth'] > max_depth:
                max_depth = node['depth']

        freq = [0] * (max_depth + 1)
        for i in range(1, len(trie)):
            if trie[i]['cnt'] >= k:
                freq[trie[i]['depth']] += 1

        best1 = 0
        for d in range(max_depth, 0, -1):
            if freq[d] > 0:
                best1 = d
                break

        if best1 == 0:
            return [0] * n

        best2 = 0
        for d in range(best1 - 1, 0, -1):
            if freq[d] > 0:
                best2 = d
                break

        ans = [0] * n

        for i, path in enumerate(word_path_nodes):
            affected_best1 = False
            for node_idx in path:
                node = trie[node_idx]
                if node['depth'] == best1 and node['cnt'] == k:
                    affected_best1 = True
                    break

            if not affected_best1:
                ans[i] = best1
                continue

            candidate = best2
            for node_idx in path:
                node = trie[node_idx]
                if node['cnt'] == k and node['depth'] > candidate:
                    candidate = node['depth'] - 1
            ans[i] = candidate

        return ans

