class Solution:
    def longestCommonPrefix(self, words: List[str], k: int) -> List[int]:
        n = len(words)
        if n - 1 < k:
            return [0] * n

        trie = [{'next': {}, 'cnt': 0, 'depth': 0}]
        word_paths = []

        for w in words:
            node = 0
            path = []
            for ch in w:
                nxt = trie[node]['next']
                if ch not in nxt:
                    nxt[ch] = len(trie)
                    trie.append({'next': {}, 'cnt': 0, 'depth': trie[node]['depth'] + 1})
                node = nxt[ch]
                trie[node]['cnt'] += 1
                path.append(node)
            word_paths.append(path)

        max_depth = 0
        depth_count = defaultdict(int)
        fragile_nodes = set()

        for i in range(1, len(trie)):
            cnt = trie[i]['cnt']
            d = trie[i]['depth']
            if cnt >= k:
                depth_count[d] += 1
                if d > max_depth:
                    max_depth = d
            if cnt == k:
                fragile_nodes.add(i)

        if max_depth == 0:
            return [0] * n

        global_best = max_depth
        global_best_count = depth_count[global_best]

        second_best = 0
        d = global_best - 1
        while d >= 1:
            if depth_count[d] > 0:
                second_best = d
                break
            d -= 1

        ans = [0] * n

        for i, path in enumerate(word_paths):
            affected_depths = []
            seen = set()
            for node in path:
                if node in fragile_nodes:
                    dep = trie[node]['depth']
                    if dep not in seen:
                        seen.add(dep)
                        affected_depths.append(dep)

            if not affected_depths:
                ans[i] = global_best
                continue

            best = global_best
            if best in seen and global_best_count == 1:
                best = second_best
                for dep in affected_depths:
                    if dep > best:
                        best = dep - 1
            ans[i] = best

        return ans

