class Solution:
    def longestCommonPrefix(self, words: List[str], k: int) -> List[int]:
        n = len(words)
        if n - 1 < k:
            return [0] * n

        trie = [{'next': {}, 'cnt': 0, 'depth': 0}]
        word_path_nodes = []

        for w in words:
            cur = 0
            path = []
            for ch in w:
                nxt = trie[cur]['next'].get(ch)
                if nxt is None:
                    nxt = len(trie)
                    trie[cur]['next'][ch] = nxt
                    trie.append({'next': {}, 'cnt': 0, 'depth': trie[cur]['depth'] + 1})
                cur = nxt
                trie[cur]['cnt'] += 1
                path.append(cur)
            word_path_nodes.append(path)

        max_depth = 0
        depth_count = defaultdict(int)
        for i in range(1, len(trie)):
            if trie[i]['cnt'] >= k:
                d = trie[i]['depth']
                depth_count[d] += 1
                if d > max_depth:
                    max_depth = d

        if max_depth == 0:
            return [0] * n

        best1 = [0] * (max_depth + 1)
        best2 = [0] * (max_depth + 1)
        freq1 = [0] * (max_depth + 1)

        for d in range(1, max_depth + 1):
            c = depth_count.get(d, 0)
            if c > 0:
                best1[d] = d
                freq1[d] = c

        suffix_best = [0] * (max_depth + 2)
        for d in range(max_depth, 0, -1):
            suffix_best[d] = best1[d] if best1[d] > suffix_best[d + 1] else suffix_best[d + 1]

        ans = [0] * n

        for idx, path in enumerate(word_path_nodes):
            affected = set()
            for node in path:
                if trie[node]['cnt'] == k:
                    affected.add(trie[node]['depth'])

            if not affected:
                ans[idx] = suffix_best[1]
                continue

            cur_best = 0
            for d in range(1, max_depth + 1):
                valid = False
                if d not in affected:
                    if depth_count.get(d, 0) > 0:
                        valid = True
                else:
                    if depth_count.get(d, 0) - 1 > 0:
                        valid = True
                if valid:
                    cur_best = d
            ans[idx] = cur_best

        return ans

