    def maxActiveSectionsAfterTrade(self, s: str) -> int:
        n = len(s)
        ones = s.count('1')

        t = '1' + s + '1'
        m = len(t)

        runs = []
        i = 0
        while i < m:
            j = i
            while j < m and t[j] == t[i]:
                j += 1
            runs.append((t[i], j - i))
            i = j

        best_gain = 0

        for k in range(1, len(runs) - 1):
            if runs[k][0] == '1':
                left_char, left_len = runs[k - 1]
                right_char, right_len = runs[k + 1]
                if left_char == '0' and right_char == '0':
                    gain = left_len + right_len
                    if gain > best_gain:
                        best_gain = gain

        return ones + best_gain

