class Solution:
    def minimumCost(self, nums, cost, k):
        n = len(nums)

        pref_nums = [0] * (n + 1)
        pref_cost = [0] * (n + 1)
        for i in range(n):
            pref_nums[i + 1] = pref_nums[i] + nums[i]
            pref_cost[i + 1] = pref_cost[i] + cost[i]

        INF = 10**30
        dp = [INF] * (n + 1)
        dp[0] = 0

        class Line:
            __slots__ = ("m", "b")
            def __init__(self, m, b):
                self.m = m
                self.b = b

            def value(self, x):
                return self.m * x + self.b

        def bad(l1, l2, l3):
            return (l3.b - l1.b) * (l1.m - l2.m) <= (l2.b - l1.b) * (l1.m - l3.m)

        hull = []
        ptr = 0

        hull.append(Line(k, 0))

        for j in range(1, n + 1):
            x = pref_cost[j]
            while ptr + 1 < len(hull) and hull[ptr + 1].value(x) <= hull[ptr].value(x):
                ptr += 1

            best = hull[ptr].value(x)
            dp[j] = pref_nums[j] * pref_cost[j] + best

            m = -pref_nums[j] - k * (j + 1)
            b = dp[j]

            new_line = Line(m, b)
            while len(hull) >= 2 and bad(hull[-2], hull[-1], new_line):
                hull.pop()
                if ptr >= len(hull):
                    ptr = len(hull) - 1
            hull.append(new_line)

        return dp[n]
